insert into public.hls_product_categories (id, name, description, image, sort_order, published) values ('farming', '{"zh":"養殖設備","zh-CN":"养殖设备","en":"Farming equipment","th":"อุปกรณ์การเกษตรและปศุสัตว์"}'::jsonb, '{"zh":"飼料儲存、自動送料、水產養殖與客製配件。","zh-CN":"饲料储存、自动送料、水产养殖与客制配件。","en":"Feed storage, automated delivery, aquaculture and custom parts.","th":"ระบบเก็บและลำเลียงอาหารอัตโนมัติ อุปกรณ์เพาะเลี้ยงสัตว์น้ำ และชิ้นส่วนสั่งทำ"}'::jsonb, 'public/assets/optimized/IMG_5058.webp', 0, true) on conflict (id) do update set name = excluded.name, description = excluded.description, image = excluded.image, sort_order = excluded.sort_order;
insert into public.hls_product_categories (id, name, description, image, sort_order, published) values ('wastewater', '{"zh":"污水處理設施","zh-CN":"污水处理设施","en":"Wastewater treatment","th":"ระบบบำบัดน้ำเสีย"}'::jsonb, '{"zh":"生活污水淨化、一般化糞池與廚房油水分離。","zh-CN":"生活污水净化、一般化粪池与厨房油水分离。","en":"Domestic treatment, septic tanks and kitchen grease separation.","th":"ถังบำบัดน้ำเสีย ถังเกรอะ และถังดักไขมันสำหรับครัว"}'::jsonb, 'public/assets/optimized/af37.webp', 1, true) on conflict (id) do update set name = excluded.name, description = excluded.description, image = excluded.image, sort_order = excluded.sort_order;
insert into public.hls_product_categories (id, name, description, image, sort_order, published) values ('storage', '{"zh":"特殊儲存設備","zh-CN":"特殊储存设备","en":"Special storage","th":"ถังเก็บเฉพาะทาง"}'::jsonb, '{"zh":"耐酸鹼化學桶槽、儲水槽與客製管件。","zh-CN":"耐酸硷化学桶槽、储水槽与客制管件。","en":"Chemical-resistant tanks, water storage and custom fittings.","th":"ถังทนสารเคมี ถังเก็บน้ำ และข้อต่อสั่งทำ"}'::jsonb, 'public/assets/optimized/xa54.webp', 2, true) on conflict (id) do update set name = excluded.name, description = excluded.description, image = excluded.image, sort_order = excluded.sort_order;
insert into public.hls_product_categories (id, name, description, image, sort_order, published) values ('sanitation', '{"zh":"整體衛浴與活動廁所","zh-CN":"整体卫浴与活动厕所","en":"Modular sanitation","th":"สุขภัณฑ์แบบโมดูลาร์"}'::jsonb, '{"zh":"快速安裝、使用便利的整體浴室及活動廁所。","zh-CN":"快速安装、使用便利的整体浴室及活动厕所。","en":"Fast-installation modular bathrooms and portable toilets.","th":"ห้องน้ำสำเร็จรูปติดตั้งรวดเร็วและสุขาเคลื่อนที่"}'::jsonb, 'public/assets/optimized/8r7q.webp', 3, true) on conflict (id) do update set name = excluded.name, description = excluded.description, image = excluded.image, sort_order = excluded.sort_order;
insert into public.hls_products (id, category_id, name, summary, features, applications, specifications, images, spec_images, videos, sort_order, published) values ('feed-system', 'farming', '{"zh":"飼料桶、自動送料設備及配件","zh-CN":"饲料桶、自动送料设备及配件","en":"Feed silos, automatic feeding systems & parts","th":"ไซโลอาหารสัตว์ ระบบให้อาหารอัตโนมัติ และอะไหล่"}'::jsonb, '{"zh":"降低人工勞動成本，提高養畜場餵養效率。","zh-CN":"降低人工劳动成本，提高养畜场喂养效率。","en":"Reduce labor and improve feeding efficiency on livestock farms.","th":"ลดแรงงานและเพิ่มประสิทธิภาพการให้อาหารในฟาร์มปศุสัตว์"}'::jsonb, '[{"zh":"自動送料系統自動操作，降低人工勞動成本，提高餵養生產效率。","zh-CN":"自动送料系统自动操作，降低人工劳动成本，提高喂养生产效率。","en":"Automatic operation lowers labor requirements and improves feeding productivity.","th":"ระบบอัตโนมัติช่วยลดแรงงานและเพิ่มประสิทธิภาพการให้อาหาร"}]'::jsonb, '{"zh":"適用於母豬舍、育肥舍、保育舍等各類牲畜舍。","zh-CN":"适用於母猪舍、育肥舍、保育舍等各类牲畜舍。","en":"Suitable for sow, finishing and nursery houses, and other livestock facilities.","th":"เหมาะสำหรับโรงเรือนแม่พันธุ์ โรงเรือนขุน โรงเรือนอนุบาล และฟาร์มปศุสัตว์ประเภทอื่น"}'::jsonb, '{"zh":"送料螺旋：2.5寸至4寸半，直徑約7.5cm；料桶容量與尺寸請參考規格表。","zh-CN":"送料螺旋：2.5寸至4寸半，直径约7.5cm；料桶容量与尺寸请参考规格表。","en":"Feed auger: 2.5 to 4.5 inches, approximately 7.5 cm diameter. See the capacity table for silo dimensions.","th":"สกรูลำเลียงอาหารขนาด 2.5–4.5 นิ้ว เส้นผ่านศูนย์กลางประมาณ 7.5 ซม. โปรดดูตารางความจุสำหรับขนาดไซโล"}'::jsonb, array['public/assets/optimized/IMG_5058.webp', 'public/assets/optimized/88s0.webp']::text[], array['public/assets/optimized/eld9.webp']::text[], '{}'::text[], 0, true) on conflict (id) do update set category_id = excluded.category_id, name = excluded.name, summary = excluded.summary, features = excluded.features, applications = excluded.applications, specifications = excluded.specifications, images = excluded.images, spec_images = excluded.spec_images, sort_order = excluded.sort_order;
insert into public.hls_products (id, category_id, name, summary, features, applications, specifications, images, spec_images, videos, sort_order, published) values ('aquaculture-tank', 'farming', '{"zh":"水產養殖槽","zh-CN":"水产养殖槽","en":"Aquaculture tanks","th":"ถังเพาะเลี้ยงสัตว์น้ำ"}'::jsonb, '{"zh":"耐腐蝕、耐摩擦、重量輕、抗衝擊且韌性佳。","zh-CN":"耐腐蚀、耐摩擦、重量轻、抗冲击且韧性佳。","en":"Corrosion resistant, wear resistant, lightweight and impact tolerant.","th":"ทนการกัดกร่อน ทนการสึกหรอ น้ำหนักเบา และทนแรงกระแทก"}'::jsonb, '[{"zh":"耐腐蝕性強、耐摩擦、重量輕、抗衝擊、韌性佳。","zh-CN":"耐腐蚀性强、耐摩擦、重量轻、抗冲击、韧性佳。","en":"Strong corrosion and wear resistance with low weight, impact resistance and toughness.","th":"ทนการกัดกร่อนและสึกหรอ น้ำหนักเบา ทนแรงกระแทก และเหนียวแข็งแรง"}]'::jsonb, '{"zh":"適用於淡水、鹽水養殖等各類漁牧業。","zh-CN":"适用於淡水、盐水养殖等各类渔牧业。","en":"Suitable for freshwater and saltwater aquaculture.","th":"เหมาะสำหรับการเพาะเลี้ยงสัตว์น้ำทั้งน้ำจืดและน้ำเค็ม"}'::jsonb, '{"zh":"可依需求客製。","zh-CN":"可依需求客制。","en":"Custom sizes are available.","th":"สามารถสั่งผลิตขนาดพิเศษได้"}'::jsonb, array['public/assets/optimized/image003_msw8.webp', 'public/assets/optimized/image005_p5fe.webp']::text[], '{}'::text[], '{}'::text[], 1, true) on conflict (id) do update set category_id = excluded.category_id, name = excluded.name, summary = excluded.summary, features = excluded.features, applications = excluded.applications, specifications = excluded.specifications, images = excluded.images, spec_images = excluded.spec_images, sort_order = excluded.sort_order;
insert into public.hls_products (id, category_id, name, summary, features, applications, specifications, images, spec_images, videos, sort_order, published) values ('transport-tank', 'farming', '{"zh":"水產運輸槽","zh-CN":"水产运输槽","en":"Aquaculture transport tanks","th":"ถังขนส่งสัตว์น้ำ"}'::jsonb, '{"zh":"堅固、耐腐蝕且容易搬運的水產運輸容器。","zh-CN":"坚固、耐腐蚀且容易搬运的水产运输容器。","en":"Durable, corrosion-resistant tanks designed for easier transport.","th":"ถังทนทานและทนการกัดกร่อน ออกแบบเพื่อความสะดวกในการขนส่ง"}'::jsonb, '[{"zh":"耐腐蝕、耐摩擦、重量輕、抗衝擊，兼具韌性與搬運便利性。","zh-CN":"耐腐蚀、耐摩擦、重量轻、抗冲击，兼具韧性与搬运便利性。","en":"Corrosion and wear resistance, low weight, impact tolerance and easy handling.","th":"ทนการกัดกร่อนและสึกหรอ น้ำหนักเบา ทนแรงกระแทก และเคลื่อนย้ายง่าย"}]'::jsonb, '{"zh":"適用於淡水、鹽水養殖與水產運輸。","zh-CN":"适用於淡水、盐水养殖与水产运输。","en":"For freshwater and saltwater aquaculture transport.","th":"สำหรับขนส่งสัตว์น้ำทั้งน้ำจืดและน้ำเค็ม"}'::jsonb, '{"zh":"可依需求客製。","zh-CN":"可依需求客制。","en":"Custom sizes are available.","th":"สามารถสั่งผลิตขนาดพิเศษได้"}'::jsonb, array['public/assets/optimized/image007_omn3.webp']::text[], '{}'::text[], '{}'::text[], 2, true) on conflict (id) do update set category_id = excluded.category_id, name = excluded.name, summary = excluded.summary, features = excluded.features, applications = excluded.applications, specifications = excluded.specifications, images = excluded.images, spec_images = excluded.spec_images, sort_order = excluded.sort_order;
insert into public.hls_products (id, category_id, name, summary, features, applications, specifications, images, spec_images, videos, sort_order, published) values ('farming-accessories', 'farming', '{"zh":"養殖設備配件","zh-CN":"养殖设备配件","en":"Farming equipment accessories","th":"อุปกรณ์เสริมสำหรับงานปศุสัตว์"}'::jsonb, '{"zh":"依現場需求製作的 FRP 養殖配件與圓形人孔蓋。","zh-CN":"依现场需求制作的 FRP 养殖配件与圆形人孔盖。","en":"Custom FRP farming accessories and circular access covers.","th":"อุปกรณ์ FRP สั่งทำสำหรับฟาร์มและฝาปิดช่องตรวจแบบกลม"}'::jsonb, '[{"zh":"耐腐蝕、耐摩擦、重量輕、抗衝擊且容易搬運。","zh-CN":"耐腐蚀、耐摩擦、重量轻、抗冲击且容易搬运。","en":"Corrosion resistant, lightweight, impact tolerant and easy to handle.","th":"ทนการกัดกร่อน น้ำหนักเบา ทนแรงกระแทก และใช้งานสะดวก"}]'::jsonb, '{"zh":"養殖設備、淡鹽水環境與客製化人孔需求。","zh-CN":"养殖设备、淡盐水环境与客制化人孔需求。","en":"Farming equipment, freshwater or saltwater environments and custom access openings.","th":"เหมาะกับอุปกรณ์ฟาร์ม สภาพแวดล้อมน้ำจืดหรือน้ำเค็ม และช่องตรวจสั่งทำ"}'::jsonb, '{"zh":"可依需求客製。","zh-CN":"可依需求客制。","en":"Custom sizes are available.","th":"สามารถสั่งผลิตขนาดพิเศษได้"}'::jsonb, array['public/assets/optimized/9msu.webp']::text[], '{}'::text[], '{}'::text[], 3, true) on conflict (id) do update set category_id = excluded.category_id, name = excluded.name, summary = excluded.summary, features = excluded.features, applications = excluded.applications, specifications = excluded.specifications, images = excluded.images, spec_images = excluded.spec_images, sort_order = excluded.sort_order;
insert into public.hls_products (id, category_id, name, summary, features, applications, specifications, images, spec_images, videos, sort_order, published) values ('domestic-treatment', 'wastewater', '{"zh":"預鑄式生活污水處理設備－淨化槽","zh-CN":"预铸式生活污水处理设备－净化槽","en":"Prefabricated domestic wastewater treatment tanks","th":"ถังบำบัดน้ำเสียสำเร็จรูป"}'::jsonb, '{"zh":"依建築用途與處理水量選型的預鑄式淨化設備。","zh-CN":"依建筑用途与处理水量选型的预铸式净化设备。","en":"Prefabricated treatment systems sized for building use and water volume.","th":"ระบบบำบัดสำเร็จรูปที่เลือกขนาดตามประเภทอาคารและปริมาณน้ำ"}'::jsonb, '[{"zh":"經環保署審定認可，可因應不同建築用途與處理水量。","zh-CN":"经环保署审定认可，可因应不同建筑用途与处理水量。","en":"Reviewed and approved by Taiwan''s environmental authority, with options for different building uses and treatment volumes.","th":"ผ่านการรับรองจากหน่วยงานสิ่งแวดล้อมไต้หวัน และมีรุ่นสำหรับอาคารกับปริมาณน้ำที่แตกต่างกัน"},{"zh":"處理廁所、廚房、浴室與洗衣等生活污水。","zh-CN":"处理厕所、厨房、浴室与洗衣等生活污水。","en":"Treats domestic wastewater from toilets, kitchens, bathrooms and laundry.","th":"บำบัดน้ำเสียจากห้องน้ำ ครัว ห้องอาบน้ำ และงานซักล้าง"}]'::jsonb, '{"zh":"依建築物用途分類及每日使用人數選擇適用尺寸。","zh-CN":"依建筑物用途分类及每日使用人数选择适用尺寸。","en":"Select the appropriate size according to building use and daily occupancy.","th":"เลือกขนาดให้เหมาะกับประเภทอาคารและจำนวนผู้ใช้งานต่อวัน"}'::jsonb, '{"zh":"HLS-010 至 HLS-100 等型號，處理容量 2.50 至 25.00 CMD；詳見規格表。","zh-CN":"HLS-010 至 HLS-100 等型号，处理容量 2.50 至 25.00 CMD；详见规格表。","en":"Models HLS-010 through HLS-100, with treatment capacities from 2.50 to 25.00 CMD. See the specification table.","th":"รุ่น HLS-010 ถึง HLS-100 รองรับ 2.50–25.00 ลูกบาศก์เมตรต่อวัน โปรดดูตารางข้อมูลจำเพาะ"}'::jsonb, array['public/assets/optimized/af37.webp']::text[], array['public/assets/optimized/c5su.webp']::text[], '{}'::text[], 4, true) on conflict (id) do update set category_id = excluded.category_id, name = excluded.name, summary = excluded.summary, features = excluded.features, applications = excluded.applications, specifications = excluded.specifications, images = excluded.images, spec_images = excluded.spec_images, sort_order = excluded.sort_order;
insert into public.hls_products (id, category_id, name, summary, features, applications, specifications, images, spec_images, videos, sort_order, published) values ('septic-tank', 'wastewater', '{"zh":"生活污水處理設備－一般化糞池","zh-CN":"生活污水处理设备－一般化粪池","en":"General septic tanks","th":"ถังเกรอะทั่วไป"}'::jsonb, '{"zh":"體積精巧、安裝簡易，適用各式住宅生活污水。","zh-CN":"体积精巧、安装简易，适用各式住宅生活污水。","en":"Compact, simple to install and suitable for residential wastewater.","th":"ขนาดกะทัดรัด ติดตั้งง่าย เหมาะสำหรับน้ำเสียจากที่พักอาศัย"}'::jsonb, '[{"zh":"安裝簡易，可依建築用途與使用人數選擇處理水量。","zh-CN":"安装简易，可依建筑用途与使用人数选择处理水量。","en":"Easy installation with treatment capacity selected by building use and occupancy.","th":"ติดตั้งง่าย และเลือกความสามารถในการบำบัดตามประเภทอาคารกับจำนวนผู้ใช้งาน"},{"zh":"處理廁所、廚房、浴室與洗衣等生活污水。","zh-CN":"处理厕所、厨房、浴室与洗衣等生活污水。","en":"Treats domestic wastewater from toilets, kitchens, bathrooms and laundry.","th":"บำบัดน้ำเสียจากห้องน้ำ ครัว ห้องอาบน้ำ และงานซักล้าง"}]'::jsonb, '{"zh":"適用各式住宅生活污水設施。","zh-CN":"适用各式住宅生活污水设施。","en":"Suitable for a wide range of residential wastewater installations.","th":"เหมาะสำหรับระบบน้ำเสียในที่พักอาศัยหลายรูปแบบ"}'::jsonb, '{"zh":"提供方型與圓型，約6人份至500人份多種規格，詳見尺寸表。","zh-CN":"提供方型与圆型，约6人份至500人份多种规格，详见尺寸表。","en":"Rectangular and cylindrical models are available from approximately 6-person to 500-person capacities.","th":"มีทั้งแบบสี่เหลี่ยมและทรงกระบอก รองรับประมาณ 6–500 คน"}'::jsonb, array['public/assets/optimized/5ceb83851f72de6a45b7b01fc0533409.webp', 'public/assets/optimized/dwyt.webp']::text[], array['public/assets/optimized/7an8.webp', 'public/assets/optimized/c8xs.webp']::text[], '{}'::text[], 5, true) on conflict (id) do update set category_id = excluded.category_id, name = excluded.name, summary = excluded.summary, features = excluded.features, applications = excluded.applications, specifications = excluded.specifications, images = excluded.images, spec_images = excluded.spec_images, sort_order = excluded.sort_order;
insert into public.hls_products (id, category_id, name, summary, features, applications, specifications, images, spec_images, videos, sort_order, published) values ('oil-separator', 'wastewater', '{"zh":"廚房油水分離槽","zh-CN":"厨房油水分离槽","en":"Kitchen grease separators","th":"ถังดักไขมันในครัว"}'::jsonb, '{"zh":"處理家庭與餐廳廚房油污水。","zh-CN":"处理家庭与餐厅厨房油污水。","en":"Separates oils and grease from household and restaurant kitchen wastewater.","th":"แยกน้ำมันและไขมันออกจากน้ำเสียในครัวเรือนและร้านอาหาร"}'::jsonb, '[{"zh":"主要功能為處理家用及餐廳廚房油污水。","zh-CN":"主要功能为处理家用及餐厅厨房油污水。","en":"Designed to treat oily wastewater from residential and restaurant kitchens.","th":"ออกแบบสำหรับบำบัดน้ำเสียที่มีไขมันจากครัวบ้านและร้านอาหาร"}]'::jsonb, '{"zh":"依每日使用水量選擇適用尺寸。","zh-CN":"依每日使用水量选择适用尺寸。","en":"Select the appropriate size based on daily water usage.","th":"เลือกขนาดตามปริมาณน้ำที่ใช้ต่อวัน"}'::jsonb, '{"zh":"可依使用量與現場條件洽詢客製。","zh-CN":"可依使用量与现场条件洽询客制。","en":"Contact us for sizing based on usage and site conditions.","th":"ติดต่อเราเพื่อเลือกขนาดตามการใช้งานและสภาพพื้นที่"}'::jsonb, array['public/assets/optimized/1jxw.webp']::text[], '{}'::text[], '{}'::text[], 6, true) on conflict (id) do update set category_id = excluded.category_id, name = excluded.name, summary = excluded.summary, features = excluded.features, applications = excluded.applications, specifications = excluded.specifications, images = excluded.images, spec_images = excluded.spec_images, sort_order = excluded.sort_order;
insert into public.hls_products (id, category_id, name, summary, features, applications, specifications, images, spec_images, videos, sort_order, published) values ('chemical-tank', 'storage', '{"zh":"耐酸鹼化學桶槽及配件","zh-CN":"耐酸硷化学桶槽及配件","en":"Chemical-resistant tanks & fittings","th":"ถังทนกรดด่างและข้อต่อ"}'::jsonb, '{"zh":"耐酸鹼、耐衝擊的一體成型工業儲存設備。","zh-CN":"耐酸硷、耐冲击的一体成型工业储存设备。","en":"One-piece industrial storage with chemical and impact resistance.","th":"ถังเก็บอุตสาหกรรมขึ้นรูปชิ้นเดียว ทนสารเคมีและแรงกระแทก"}'::jsonb, '[{"zh":"質地堅韌，搬運簡便，耐震、耐衝擊。","zh-CN":"质地坚韧，搬运简便，耐震、耐冲击。","en":"Tough construction for easy handling, vibration resistance and impact tolerance.","th":"โครงสร้างแข็งแรง เคลื่อนย้ายง่าย ทนการสั่นสะเทือนและแรงกระแทก"},{"zh":"對各類酸、鹼具有優良抗腐蝕性。","zh-CN":"对各类酸、硷具有优良抗腐蚀性。","en":"Excellent resistance to a wide range of acids and alkalis.","th":"ทนกรดและด่างหลากหลายชนิดได้ดีเยี่ยม"},{"zh":"流線外型容易清潔，不易藏污。","zh-CN":"流线外型容易清洁，不易藏污。","en":"Streamlined surfaces are easy to clean.","th":"พื้นผิวเรียบลื่น ทำความสะอาดง่าย"},{"zh":"桶體一體成型，不易破裂，兼具耐熱與耐凍性。","zh-CN":"桶体一体成型，不易破裂，兼具耐热与耐冻性。","en":"One-piece construction resists cracking and performs across hot and cold conditions.","th":"โครงสร้างชิ้นเดียวลดการแตกร้าว และใช้งานได้ทั้งสภาพร้อนและเย็น"}]'::jsonb, '{"zh":"適用於儲水及工業用酸、鹼液體儲存。","zh-CN":"适用於储水及工业用酸、硷液体储存。","en":"Suitable for water and industrial acid or alkaline liquid storage.","th":"เหมาะสำหรับเก็บน้ำและของเหลวกรดหรือด่างในอุตสาหกรรม"}'::jsonb, '{"zh":"可依需求客製。","zh-CN":"可依需求客制。","en":"Custom sizes are available.","th":"สามารถสั่งผลิตขนาดพิเศษได้"}'::jsonb, array['public/assets/optimized/image013_q6j5.webp', 'public/assets/optimized/j5y2.webp']::text[], '{}'::text[], '{}'::text[], 7, true) on conflict (id) do update set category_id = excluded.category_id, name = excluded.name, summary = excluded.summary, features = excluded.features, applications = excluded.applications, specifications = excluded.specifications, images = excluded.images, spec_images = excluded.spec_images, sort_order = excluded.sort_order;
insert into public.hls_products (id, category_id, name, summary, features, applications, specifications, images, spec_images, videos, sort_order, published) values ('water-tank', 'storage', '{"zh":"儲水槽","zh-CN":"储水槽","en":"Water storage tanks","th":"ถังเก็บน้ำ"}'::jsonb, '{"zh":"堅韌、美觀、經濟耐用的一體成型 FRP 儲水槽。","zh-CN":"坚韧、美观、经济耐用的一体成型 FRP 储水槽。","en":"Tough, clean-looking and economical one-piece FRP water storage.","th":"ถังเก็บน้ำ FRP ชิ้นเดียว แข็งแรง สะอาด และคุ้มค่า"}'::jsonb, '[{"zh":"質地堅韌，搬運簡便，耐震、耐衝擊。","zh-CN":"质地坚韧，搬运简便，耐震、耐冲击。","en":"Tough construction, easy handling and impact resistance.","th":"โครงสร้างแข็งแรง เคลื่อนย้ายง่าย และทนแรงกระแทก"},{"zh":"外型流線美觀、不易藏污，容易清潔。","zh-CN":"外型流线美观、不易藏污，容易清洁。","en":"Smooth surfaces resist dirt and are easy to clean.","th":"พื้นผิวเรียบ ไม่สะสมสิ่งสกปรก และทำความสะอาดง่าย"},{"zh":"桶體一體成型，不易破裂。","zh-CN":"桶体一体成型，不易破裂。","en":"One-piece construction resists cracking.","th":"โครงสร้างชิ้นเดียวช่วยป้องกันการแตกร้าว"}]'::jsonb, '{"zh":"適用於各類儲水需求。","zh-CN":"适用於各类储水需求。","en":"Suitable for a variety of water storage applications.","th":"เหมาะสำหรับงานเก็บน้ำหลายประเภท"}'::jsonb, '{"zh":"可依需求客製。","zh-CN":"可依需求客制。","en":"Custom sizes are available.","th":"สามารถสั่งผลิตขนาดพิเศษได้"}'::jsonb, array['public/assets/optimized/xa54.webp']::text[], '{}'::text[], '{}'::text[], 8, true) on conflict (id) do update set category_id = excluded.category_id, name = excluded.name, summary = excluded.summary, features = excluded.features, applications = excluded.applications, specifications = excluded.specifications, images = excluded.images, spec_images = excluded.spec_images, sort_order = excluded.sort_order;
insert into public.hls_products (id, category_id, name, summary, features, applications, specifications, images, spec_images, videos, sort_order, published) values ('integrated-bathroom', 'sanitation', '{"zh":"整體浴室","zh-CN":"整体浴室","en":"Integrated bathrooms","th":"ห้องน้ำสำเร็จรูป"}'::jsonb, '{"zh":"符合日常使用習慣，快速安裝、方便使用。","zh-CN":"符合日常使用习惯，快速安装、方便使用。","en":"Familiar, convenient facilities in a fast-installation modular unit.","th":"ห้องน้ำโมดูลาร์ใช้งานสะดวกและติดตั้งรวดเร็ว"}'::jsonb, '[{"zh":"符合一般如廁習慣、安裝迅速、使用方便。","zh-CN":"符合一般如厕习惯、安装迅速、使用方便。","en":"Designed around familiar routines, with quick installation and convenient use.","th":"ออกแบบตามพฤติกรรมการใช้งานทั่วไป ติดตั้งเร็ว และใช้งานสะดวก"}]'::jsonb, '{"zh":"適用於具備上下水與排水系統，或不便建造固定廁所的住宅、公園、景點、園林與社區等場地。","zh-CN":"适用於具备上下水与排水系统，或不便建造固定厕所的住宅、公园、景点、园林与社区等场地。","en":"For sites with water and drainage access or where permanent construction is impractical, including housing, parks, attractions and communities.","th":"เหมาะสำหรับพื้นที่ที่มีระบบน้ำและระบายน้ำ หรือพื้นที่ที่สร้างห้องน้ำถาวรได้ยาก เช่น ที่พัก สวนสาธารณะ แหล่งท่องเที่ยว และชุมชน"}'::jsonb, '{"zh":"整體浴室：147 × 132 × 230 cm；可拆整體浴室：150 × 150 × 230 cm。","zh-CN":"整体浴室：147 × 132 × 230 cm；可拆整体浴室：150 × 150 × 230 cm。","en":"Integrated bathroom: 147 × 132 × 230 cm. Demountable unit: 150 × 150 × 230 cm.","th":"ห้องน้ำสำเร็จรูป 147 × 132 × 230 ซม. รุ่นถอดประกอบ 150 × 150 × 230 ซม."}'::jsonb, array['public/assets/optimized/8r7q.webp']::text[], array['public/assets/optimized/yxb9.webp']::text[], '{}'::text[], 9, true) on conflict (id) do update set category_id = excluded.category_id, name = excluded.name, summary = excluded.summary, features = excluded.features, applications = excluded.applications, specifications = excluded.specifications, images = excluded.images, spec_images = excluded.spec_images, sort_order = excluded.sort_order;
insert into public.hls_products (id, category_id, name, summary, features, applications, specifications, images, spec_images, videos, sort_order, published) values ('portable-toilet', 'sanitation', '{"zh":"活動廁所","zh-CN":"活动厕所","en":"Portable toilets","th":"สุขาเคลื่อนที่"}'::jsonb, '{"zh":"適合臨時與彈性場域配置的 FRP 活動廁所。","zh-CN":"适合临时与弹性场域配置的 FRP 活动厕所。","en":"FRP portable toilets for temporary and flexible site requirements.","th":"สุขาเคลื่อนที่ FRP สำหรับพื้นที่ชั่วคราวและการจัดวางที่ยืดหยุ่น"}'::jsonb, '[{"zh":"FRP 外殼耐用、重量相對輕，便於場地配置。","zh-CN":"FRP 外壳耐用、重量相对轻，便於场地配置。","en":"Durable, comparatively lightweight FRP shell for flexible placement.","th":"เปลือก FRP ทนทาน น้ำหนักค่อนข้างเบา และเคลื่อนย้ายจัดวางได้ง่าย"}]'::jsonb, '{"zh":"適用工地、活動、公園、景區與臨時設施。","zh-CN":"适用工地、活动、公园、景区与临时设施。","en":"Suitable for construction sites, events, parks, attractions and temporary facilities.","th":"เหมาะสำหรับไซต์ก่อสร้าง งานกิจกรรม สวนสาธารณะ แหล่งท่องเที่ยว และสถานที่ชั่วคราว"}'::jsonb, '{"zh":"可依設備內容與現場需求洽詢。","zh-CN":"可依设备内容与现场需求洽询。","en":"Contact us for configuration and sizing options.","th":"ติดต่อเราเพื่อสอบถามรูปแบบและขนาดที่เหมาะสม"}'::jsonb, array['public/assets/optimized/6i5l.webp', 'public/assets/optimized/ucdb.webp']::text[], '{}'::text[], '{}'::text[], 10, true) on conflict (id) do update set category_id = excluded.category_id, name = excluded.name, summary = excluded.summary, features = excluded.features, applications = excluded.applications, specifications = excluded.specifications, images = excluded.images, spec_images = excluded.spec_images, sort_order = excluded.sort_order;
insert into public.hls_news (id, title, summary, body, source, author, views, published_at, sort_order, published) values (21, '{"zh":"散裝飼料助現代畜牧業提質增效","zh-CN":"散装饲料助现代畜牧业提质增效","en":"Bulk feed improves quality and efficiency in modern livestock farming","th":"อาหารสัตว์แบบเทกองช่วยยกระดับคุณภาพและประสิทธิภาพของปศุสัตว์สมัยใหม่"}'::jsonb, '{"zh":"飼料是現代養殖業發展的物質基礎，散裝飼料與自動喂料系統的結合可提升效率并節省人力成本。","zh-CN":"饲料是现代养殖业发展的物质基础，散装饲料与自动喂料系统的结合可提升效率并节省人力成本。","en":"Bulk feed and automated feeding systems can improve efficiency, reduce handling and lower labor costs.","th":"อาหารสัตว์แบบเทกองร่วมกับระบบให้อาหารอัตโนมัติช่วยเพิ่มประสิทธิภาพ ลดการขนย้าย และลดต้นทุนแรงงาน"}'::jsonb, '[{"zh":"飼料是現代養殖業發展的物質基礎，充足穩定、便捷高效、安全環保的飼料供給，對促進養殖業持續健康發展、保障動物性食品質量安全具有重要意義。為順應畜牧業轉型升級需要，推進飼料供給側結構性改革，‘十三五’期間，農業部和各級畜牧飼料管理部門，將積極推進散裝飼料與養殖場緊密連接，實現養殖業提質增效。近日，記者來到江蘇省新沂市，實地探訪散裝飼料在飼料企業和規模養殖場的推廣效果。","zh-CN":"饲料是现代养殖业发展的物质基础，充足稳定、便捷高效、安全环保的饲料供给，对促进养殖业持续健康发展、保障动物性食品质量安全具有重要意义。为顺应畜牧业转型升级需要，推进饲料供给侧结构性改革，‘十三五’期间，农业部和各级畜牧饲料管理部门，将积极推进散装饲料与养殖场紧密连接，实现养殖业提质增效。近日，记者来到江苏省新沂市，实地探访散装饲料在饲料企业和规模养殖场的推广效果。","en":"Feed is the material foundation of modern livestock farming. A stable, efficient, safe and environmentally responsible supply supports sustainable production and food safety. During the 13th Five-Year Plan, agricultural authorities promoted closer links between bulk-feed suppliers and farms. A field visit to Xinyi, Jiangsu, examined how this approach was working in feed mills and large farms.","th":"อาหารสัตว์เป็นรากฐานของปศุสัตว์สมัยใหม่ การจัดหาที่มั่นคง มีประสิทธิภาพ ปลอดภัย และเป็นมิตรต่อสิ่งแวดล้อม ช่วยสนับสนุนการผลิตที่ยั่งยืนและความปลอดภัยทางอาหาร หน่วยงานเกษตรจึงผลักดันการเชื่อมโยงอาหารสัตว์แบบเทกองกับฟาร์มอย่างใกล้ชิด โดยมีการสำรวจผลการใช้งานที่เมืองซินอี มณฑลเจียงซู"},{"zh":"飼料廠養殖場實現無縫對接","zh-CN":"饲料厂养殖场实现无缝对接","en":"A seamless link between feed mill and farm","th":"เชื่อมต่อโรงงานอาหารสัตว์กับฟาร์มอย่างไร้รอยต่อ"},{"zh":"在江蘇省新沂市的中糧飼料廠內，飼料正在通過出料口裝進罐裝車中，整個過程10分鐘，僅需要一位工人進行控制。裝滿飼料的罐裝車將立刻發往養殖場。","zh-CN":"在江苏省新沂市的中粮饲料厂内，饲料正在通过出料口装进罐装车中，整个过程10分钟，仅需要一位工人进行控制。装满饲料的罐装车将立刻发往养殖场。","en":"At the COFCO feed mill in Xinyi, feed is loaded directly into a bulk tanker through an outlet. The entire process takes about ten minutes and requires only one operator, after which the vehicle departs for the farm.","th":"ที่โรงงานอาหารสัตว์ COFCO เมืองซินอี อาหารถูกส่งผ่านช่องจ่ายเข้าสู่รถแทงก์โดยตรง ใช้เวลาประมาณสิบนาทีและมีผู้ควบคุมเพียงหนึ่งคน จากนั้นรถจะออกเดินทางไปยังฟาร์มทันที"},{"zh":"現在年產能力24萬噸的新沂中糧飼料廠，共有60噸/個散料發放塔6個，3個出料口。目前，散裝飼料已占其總產量的40%，是一個不小的比例。","zh-CN":"现在年产能力24万吨的新沂中粮饲料厂，共有60吨/个散料发放塔6个，3个出料口。目前，散装饲料已占其总产量的40%，是一个不小的比例。","en":"The Xinyi mill has annual capacity of 240,000 tonnes, six 60-tonne bulk dispatch silos and three loading outlets. Bulk feed already accounts for about 40% of its production.","th":"โรงงานมีกำลังผลิตปีละ 240,000 ตัน มีไซโลจ่ายอาหารขนาด 60 ตันจำนวนหกชุดและช่องจ่ายสามช่อง ปัจจุบันอาหารแบบเทกองคิดเป็นประมาณ 40% ของผลผลิตทั้งหมด"},{"zh":"據公司副總經理肖培新介紹，散裝飼料的生產可實現直接生產直接裝車，隨產隨出，不需要進行提前備貨，不占用倉儲設施，也不會出現停產等待拉料的現象，使飼料生產實現計劃管理，生產效率得到提升。","zh-CN":"据公司副总经理肖培新介绍，散装饲料的生产可实现直接生产直接装车，随产随出，不需要进行提前备货，不占用仓储设施，也不会出现停产等待拉料的现象，使饲料生产实现计划管理，生产效率得到提升。","en":"Deputy general manager Xiao Peixin explained that bulk production allows feed to move directly from production to the vehicle. It reduces advance inventory and warehouse use, avoids production stoppages while waiting for collection, and improves planned production and efficiency.","th":"รองผู้จัดการใหญ่ เซียวเผยซิน อธิบายว่าระบบเทกองช่วยให้ผลิตแล้วขึ้นรถได้ทันที ลดสินค้าคงคลังและพื้นที่คลังสินค้า ไม่ต้องหยุดรอรถรับสินค้า และช่วยให้วางแผนการผลิตได้มีประสิทธิภาพขึ้น"},{"zh":"散裝飼料運輸車結構簡單，有著較大的輸送量，一般在20噸左右。全自動上料卸料，節省人力，節約費用，可連續作業，大大提高了運載效率。每輛散裝車均打上鉛封，根據鉛封號可做到每車料的全程追溯。同時，散裝飼料在散裝車罐體內密封輸送，可以減少損耗，避免污染，保證了散裝飼料的質量安全。","zh-CN":"散装饲料运输车结构简单，有着较大的输送量，一般在20吨左右。全自动上料卸料，节省人力，节约费用，可连续作业，大大提高了运载效率。每辆散装车均打上铅封，根据铅封号可做到每车料的全程追溯。同时，散装饲料在散装车罐体内密封输送，可以减少损耗，避免污染，保证了散装饲料的质量安全。","en":"Bulk-feed tankers have a simple structure and usually carry around 20 tonnes. Automated loading and unloading save labor and support continuous operation. Each vehicle is sealed and traceable, while enclosed transport reduces loss and contamination and protects feed quality.","th":"รถขนอาหารเทกองมีโครงสร้างเรียบง่ายและมักบรรทุกประมาณ 20 ตัน ระบบขึ้นและลงสินค้าอัตโนมัติช่วยลดแรงงาน ทำงานต่อเนื่องได้ รถทุกคันมีซีลเพื่อการตรวจสอบย้อนกลับ และการขนส่งแบบปิดช่วยลดการสูญเสียกับการปนเปื้อน"},{"zh":"對于養殖場飼喂環節，散裝飼料車直接卸料進飼料罐中，飼養員在飼喂過程中只需要點動絞龍開關，即可實現自動投料，不需要人工割包倒料的過程，提高了飼喂效率。散裝飼料與自動喂料系統的結合，大大節約了養殖人力成本。記者參觀的一個存欄母豬1000頭的飼養場，只需2人負責飼喂過程的巡查。","zh-CN":"对于养殖场饲喂环节，散装饲料车直接卸料进饲料罐中，饲养员在饲喂过程中只需要点动绞龙开关，即可实现自动投料，不需要人工割包倒料的过程，提高了饲喂效率。散装饲料与自动喂料系统的结合，大大节约了养殖人力成本。记者参观的一个存栏母猪1000头的饲养场，只需2人负责饲喂过程的巡查。","en":"At the farm, feed is discharged directly into the silo. Operators can feed animals by activating the auger rather than opening and carrying bags. Combining bulk feed with automatic feeding greatly reduces labor; one 1,000-sow farm needed only two people to monitor feeding.","th":"เมื่อถึงฟาร์ม อาหารจะถูกถ่ายเข้าสู่ไซโลโดยตรง ผู้เลี้ยงเพียงเปิดสกรูลำเลียงก็สามารถให้อาหารได้ ไม่ต้องเปิดและเทถุง การทำงานร่วมกับระบบให้อาหารอัตโนมัติช่วยลดแรงงานอย่างมาก โดยฟาร์มแม่สุกร 1,000 ตัวใช้คนเพียงสองคนตรวจระบบ"},{"zh":"一位養殖企業負責人告訴記者，飼料散裝散運能夠實現飼料廠和養殖場的無縫對接，從而保證飼料的質量和生物安全。散裝飼料在散裝車罐體內密封輸送，可以減少損耗，從飼料加工到養殖場飼喂系統最終到動物口中全程無人為接觸，避免污染，保證飼料的質量和畜產品安全，降低養殖場和飼料廠生產運營風險。","zh-CN":"一位养殖企业负责人告诉记者，饲料散装散运能够实现饲料厂和养殖场的无缝对接，从而保证饲料的质量和生物安全。散装饲料在散装车罐体内密封输送，可以减少损耗，从饲料加工到养殖场饲喂系统最终到动物口中全程无人为接触，避免污染，保证饲料的质量和畜产品安全，降低养殖场和饲料厂生产运营风险。","en":"A farm manager said bulk transport creates a seamless connection between mill and farm, helping protect quality and biosecurity. From processing to the feeding system and finally the animal, enclosed handling minimizes human contact, contamination, product loss and operating risk.","th":"ผู้บริหารฟาร์มระบุว่าการขนส่งแบบเทกองเชื่อมโรงงานกับฟาร์มโดยตรง ช่วยรักษาคุณภาพและความปลอดภัยทางชีวภาพ ตั้งแต่การผลิตจนถึงสัตว์กินอาหาร กระบวนการแบบปิดลดการสัมผัส การปนเปื้อน การสูญเสีย และความเสี่ยงในการดำเนินงาน"},{"zh":"此外，散裝飼料無需包裝，大大減少了塑料編織袋對環境造成的污染。同時，散裝飼料運輸車罐體全部采用密封性設計，因而在運輸過程中對周邊環境無污染，具有很好的社會效益。","zh-CN":"此外，散装饲料无需包装，大大减少了塑料编织袋对环境造成的污染。同时，散装饲料运输车罐体全部采用密封性设计，因而在运输过程中对周边环境无污染，具有很好的社会效益。","en":"Bulk feed also removes the need for woven plastic bags. Sealed tanker bodies prevent spillage and pollution during transport, creating wider environmental and social benefits.","th":"อาหารแบบเทกองไม่ต้องใช้ถุงพลาสติกสาน และตัวถังรถที่ปิดสนิทช่วยป้องกันการหกหรือมลพิษระหว่างขนส่ง จึงให้ประโยชน์ทั้งด้านสิ่งแวดล้อมและสังคม"},{"zh":"散裝散運散用是多贏之舉","zh-CN":"散装散运散用是多赢之举","en":"Bulk production, transport and use benefit all parties","th":"การผลิต ขนส่ง และใช้อาหารแบบเทกองให้ประโยชน์แก่ทุกฝ่าย"},{"zh":"散裝飼料優點明顯，然而要真正推廣開，還需要市場的推動，讓企業看到使用散裝飼料的好處，并獲得更多收益。我國飼料企業每年生產的商品飼料超過2億噸。據測算，在傳統袋裝銷售模式下，每年飼料企業僅在包裝、標簽、裝卸方面的投入就達到140億元。","zh-CN":"散装饲料优点明显，然而要真正推广开，还需要市场的推动，让企业看到使用散装饲料的好处，并获得更多收益。我国饲料企业每年生产的商品饲料超过2亿吨。据测算，在传统袋装销售模式下，每年饲料企业仅在包装、标签、装卸方面的投入就达到140亿元。","en":"The advantages are clear, but wider adoption still depends on market demand and visible returns. China produces more than 200 million tonnes of commercial feed each year, while packaging, labeling and handling under the bagged model represent substantial annual costs.","th":"แม้ข้อดีจะชัดเจน แต่การขยายตลาดยังต้องอาศัยผลตอบแทนที่ธุรกิจมองเห็น จีนผลิตอาหารสัตว์เชิงพาณิชย์มากกว่า 200 ล้านตันต่อปี ขณะที่ระบบบรรจุถุงมีต้นทุนด้านบรรจุภัณฑ์ ฉลาก และการขนถ่ายจำนวนมาก"},{"zh":"在引入散裝飼料之前，中糧飼料（新沂）公司進行了周密的市場調研，發現目前畜禽養殖越來越朝著規模化發展，為了提高工作效率，降低人工成本，越來越多的大中型養殖場開始使用自動喂料塔，作為養殖場內部飼料暫存、飼喂裝置。經過多方面現場走訪、測算，認為散裝飼料需求空間廣闊，不僅能夠降低供需方成本，還能提升效率，保證產品新鮮度。推行飼料直供模式，還能減少中間環節，縮短銷售周期，提升終端服務與競爭力。","zh-CN":"在引入散装饲料之前，中粮饲料（新沂）公司进行了周密的市场调研，发现目前畜禽养殖越来越朝着规模化发展，为了提高工作效率，降低人工成本，越来越多的大中型养殖场开始使用自动喂料塔，作为养殖场内部饲料暂存、饲喂装置。经过多方面现场走访、测算，认为散装饲料需求空间广阔，不仅能够降低供需方成本，还能提升效率，保证产品新鲜度。推行饲料直供模式，还能减少中间环节，缩短销售周期，提升终端服务与竞争力。","en":"Before introducing bulk feed, COFCO Xinyi studied the market and found that larger farms increasingly use automatic silos to improve efficiency and reduce labor. Field research indicated strong demand: direct supply can lower costs, improve freshness, shorten sales cycles and strengthen service and competitiveness.","th":"ก่อนนำระบบมาใช้ COFCO ซินอีได้ศึกษาตลาดและพบว่าฟาร์มขนาดใหญ่ใช้ไซโลอัตโนมัติมากขึ้นเพื่อลดแรงงานและเพิ่มประสิทธิภาพ การจัดส่งตรงช่วยลดต้นทุน รักษาความสด ลดขั้นตอนการขาย และเพิ่มความสามารถในการแข่งขัน"},{"zh":"肖培新給記者算了筆賬，袋裝飼料的包材費約為30元/噸，而散裝飼料不需要包裝。一并減少的還有打包費、發貨人工費、叉車費等。算下來，在生產環節中散裝飼料要比袋裝飼料每噸節省36元。在運費方面，以向宿遷肉食公司運輸為例，散裝車運輸（20噸/車）運費約為78元/噸，袋裝運輸（20噸/車）運費約為60元/噸，差距在18元/噸。雖然散裝飼料運輸成本高一些，但總體來看明顯劃算。","zh-CN":"肖培新给记者算了笔账，袋装饲料的包材费约为30元/吨，而散装饲料不需要包装。一并减少的还有打包费、发货人工费、叉车费等。算下来，在生产环节中散装饲料要比袋装饲料每吨节省36元。在运费方面，以向宿迁肉食公司运输为例，散装车运输（20吨/车）运费约为78元/吨，袋装运输（20吨/车）运费约为60元/吨，差距在18元/吨。虽然散装饲料运输成本高一些，但总体来看明显划算。","en":"Xiao estimated packaging alone at about RMB 30 per tonne for bagged feed. Together with packing, labor and forklift costs, bulk production saved about RMB 36 per tonne. Tanker freight could cost more, but the total operating economics remained favorable.","th":"เซียวคำนวณว่าค่าบรรจุภัณฑ์ของอาหารแบบถุงอยู่ที่ประมาณ 30 หยวนต่อตัน เมื่อรวมค่าบรรจุ แรงงาน และรถยก ระบบเทกองประหยัดในขั้นผลิตได้ราว 36 หยวนต่อตัน แม้ค่าขนส่งรถแทงก์สูงกว่า แต่โดยรวมยังคุ้มค่า"},{"zh":"對于養殖企業，散裝飼料省去了裝卸成本，節省人工成本。散裝車（20噸/車）卸車費約為2.5元/噸，袋裝運輸（20噸/車）卸車費約為8元/噸，差距在5.5元/噸。而對于一些與飼料廠聯系緊密的大型養殖企業，散裝飼料的優勢更明顯。","zh-CN":"对于养殖企业，散装饲料省去了装卸成本，节省人工成本。散装车（20吨/车）卸车费约为2.5元/吨，袋装运输（20吨/车）卸车费约为8元/吨，差距在5.5元/吨。而对于一些与饲料厂联系紧密的大型养殖企业，散装饲料的优势更明显。","en":"Farms also save unloading and labor expenses. The example compared unloading at about RMB 2.5 per tonne for bulk delivery and RMB 8 per tonne for bagged feed. Benefits are even greater for large farms closely connected with a feed mill.","th":"ฟาร์มยังลดค่าขนถ่ายและแรงงานได้ ตัวอย่างเปรียบเทียบค่าลงอาหารเทกองประมาณ 2.5 หยวนต่อตัน กับอาหารแบบถุงประมาณ 8 หยวนต่อตัน โดยฟาร์มใหญ่ที่เชื่อมโยงกับโรงงานใกล้ชิดจะได้ประโยชน์มากขึ้น"},{"zh":"‘在當下市場競爭越來越激烈的環境下，對于飼料企業和養殖企業，使用散裝發貨都是雙贏之舉。’肖培新說。","zh-CN":"‘在当下市场竞争越来越激烈的环境下，对于饲料企业和养殖企业，使用散装发货都是双赢之举。’肖培新说。","en":"In an increasingly competitive market, bulk delivery is a win-win choice for both feed suppliers and livestock farms, Xiao said.","th":"ในตลาดที่แข่งขันสูง การจัดส่งแบบเทกองเป็นทางเลือกที่ได้ประโยชน์ร่วมกันทั้งโรงงานอาหารสัตว์และฟาร์ม เซียวกล่าว"},{"zh":"讓散裝飼料設備享受農機補貼","zh-CN":"让散装饲料设备享受农机补贴","en":"Extend agricultural machinery subsidies to bulk-feed equipment","th":"ขยายเงินอุดหนุนเครื่องจักรเกษตรสู่อุปกรณ์อาหารสัตว์แบบเทกอง"},{"zh":"散裝飼料目前仍處于初步推廣階段，據了解，散裝飼料只占飼料總產量的10%左右，‘十三五’期間爭取有較快的提升。","zh-CN":"散装饲料目前仍处于初步推广阶段，据了解，散装饲料只占饲料总产量的10%左右，‘十三五’期间争取有较快的提升。","en":"Bulk feed was still at an early adoption stage and represented about 10% of total production. The industry aimed for faster growth during the 13th Five-Year Plan.","th":"ขณะนั้นอาหารแบบเทกองยังอยู่ในช่วงเริ่มต้นและมีสัดส่วนประมาณ 10% ของผลผลิตทั้งหมด อุตสาหกรรมตั้งเป้าให้เติบโตเร็วขึ้นในช่วงแผนห้าปีฉบับที่ 13"},{"zh":"從袋裝飼料改為散裝飼料意味著整套養殖設備的改造，需要建設成品料塔和自動上料機等配套機械化喂料設備，會使養殖企業增加一次性成本投入。散裝飼料的推廣應用還受養殖規模的限制，散裝飼料節省人工的優勢只有達到一定規模后才能體現出來。為了鼓勵養殖企業使用散裝飼料，一些飼料生產企業為養殖企業無償建成品料塔和自動上料機等配套機械化喂料設備，前提是在一定時期內使用該企業產品，形成了較緊密的利益連結機制。","zh-CN":"从袋装饲料改为散装饲料意味着整套养殖设备的改造，需要建设成品料塔和自动上料机等配套机械化喂料设备，会使养殖企业增加一次性成本投入。散装饲料的推广应用还受养殖规模的限制，散装饲料节省人工的优势只有达到一定规模后才能体现出来。为了鼓励养殖企业使用散装饲料，一些饲料生产企业为养殖企业无偿建成品料塔和自动上料机等配套机械化喂料设备，前提是在一定时期内使用该企业产品，形成了较紧密的利益连结机制。","en":"Moving from bags to bulk requires investment in finished-feed silos, automatic loaders and related equipment. Labor savings appear only beyond a certain farm scale. Some feed producers therefore supplied equipment at no charge in exchange for a period of product use, creating closer commercial partnerships.","th":"การเปลี่ยนจากถุงเป็นเทกองต้องลงทุนในไซโล เครื่องป้อนอัตโนมัติ และอุปกรณ์ที่เกี่ยวข้อง อีกทั้งประโยชน์ด้านแรงงานจะเห็นชัดเมื่อฟาร์มมีขนาดเพียงพอ ผู้ผลิตบางรายจึงสนับสนุนอุปกรณ์โดยแลกกับการใช้ผลิตภัณฑ์ในช่วงเวลาที่กำหนด"},{"zh":"‘由于傳統養殖習慣，一部分養殖企業還不接受散裝飼料，不樂意使用散裝飼料。’當地飼料管理部門同志說。思想的轉變需要時間，需要各級畜牧飼料管理部門大力宣傳推廣散裝飼料，重點從飼料廠和養殖企業兩個方面入手，使全社會認識到飼料散裝散運和養殖場散用的經濟效益、社會效益和生態效益。","zh-CN":"‘由于传统养殖习惯，一部分养殖企业还不接受散装饲料，不乐意使用散装饲料。’当地饲料管理部门同志说。思想的转变需要时间，需要各级畜牧饲料管理部门大力宣传推广散装饲料，重点从饲料厂和养殖企业两个方面入手，使全社会认识到饲料散装散运和养殖场散用的经济效益、社会效益和生态效益。","en":"Some farms remained hesitant because of established practices. Agricultural and feed authorities therefore needed to explain the economic, social and ecological value of bulk production, transport and on-farm use to both mills and livestock businesses.","th":"ฟาร์มบางส่วนยังลังเลเพราะความเคยชินเดิม หน่วยงานปศุสัตว์และอาหารสัตว์จึงควรสื่อสารคุณค่าด้านเศรษฐกิจ สังคม และสิ่งแวดล้อมของระบบเทกองแก่ทั้งโรงงานและผู้เลี้ยง"},{"zh":"另一方面，亟待落實農機補貼對飼料散裝散運工作的支持。雖然農業部已經將養殖場成品料塔、自動上料機和飼料生產企業散裝飼料運輸車等養殖設備納入農機補貼范疇，但是從基層農機部門了解，目前很少有散裝飼料設備和畜禽養殖設施享受到此項政策。在推廣散裝飼料工作中，農機購機補貼是覆蓋面最廣、可操作性最強、支持最直接的普惠扶持政策。各級畜牧飼料管理部門要加強與農機部門的協調力度，把散裝飼料設備納入地方農機補貼目錄作為突破口，組織養殖場、設備生產企業等開展技術交流，規范設備制造標準。各級農機管理部門要加強對散裝飼料設備納入農機補貼目錄的指導和研究，穩步推進補貼政策惠及散裝飼料設備。政府還應在稅收和信貸方面予以專項重點扶持，以調動企業的積極性。","zh-CN":"另一方面，亟待落实农机补贴对饲料散装散运工作的支持。虽然农业部已经将养殖场成品料塔、自动上料机和饲料生产企业散装饲料运输车等养殖设备纳入农机补贴范畴，但是从基层农机部门了解，目前很少有散装饲料设备和畜禽养殖设施享受到此项政策。在推广散装饲料工作中，农机购机补贴是覆盖面最广、可操作性最强、支持最直接的普惠扶持政策。各级畜牧饲料管理部门要加强与农机部门的协调力度，把散装饲料设备纳入地方农机补贴目录作为突破口，组织养殖场、设备生产企业等开展技术交流，规范设备制造标准。各级农机管理部门要加强对散装饲料设备纳入农机补贴目录的指导和研究，稳步推进补贴政策惠及散装饲料设备。政府还应在税收和信贷方面予以专项重点扶持，以调动企业的积极性。","en":"The article also called for effective machinery subsidies. Authorities were encouraged to add bulk-feed equipment to local subsidy catalogues, coordinate technical exchange, improve manufacturing standards, and provide suitable tax and credit support so more farms and manufacturers could adopt the system.","th":"บทความยังเสนอให้ดำเนินนโยบายอุดหนุนอย่างจริงจัง เพิ่มอุปกรณ์เทกองในบัญชีท้องถิ่น ประสานการแลกเปลี่ยนเทคนิค ยกระดับมาตรฐานการผลิต และสนับสนุนด้านภาษีกับสินเชื่อเพื่อให้ฟาร์มและผู้ผลิตนำระบบไปใช้ได้มากขึ้น"}]'::jsonb, '{"zh":"農民日報","zh-CN":"农民日报","en":"Farmers'' Daily","th":"หนังสือพิมพ์เกษตรกร"}'::jsonb, 'hkfb16ff', 4556, '2016-11-15'::date, 0, true) on conflict (id) do update set title = excluded.title, summary = excluded.summary, body = excluded.body, source = excluded.source, author = excluded.author, views = excluded.views, published_at = excluded.published_at, sort_order = excluded.sort_order;
insert into public.hls_news (id, title, summary, body, source, author, views, published_at, sort_order, published) values (10, '{"zh":"中國奶牛養殖及養殖設備情況研究報告大綱","zh-CN":"中国奶牛养殖及养殖设备情况研究报告大纲","en":"Research outline on dairy farming and equipment in China","th":"โครงร่างงานวิจัยการเลี้ยงโคนมและอุปกรณ์ในจีน"}'::jsonb, '{"zh":"在畜禽養殖生產中，冬季加熱與現代化設備對生產效率與管理具有重要影響。","zh-CN":"在畜禽养殖生产中，冬季加热与现代化设备对生产效率与管理具有重要影响。","en":"Winter heating and modern equipment can have an important impact on livestock productivity and operations.","th":"ระบบทำความร้อนในฤดูหนาวและอุปกรณ์สมัยใหม่มีผลสำคัญต่อประสิทธิภาพและการจัดการฟาร์มปศุสัตว์"}'::jsonb, '[{"zh":"在畜禽養殖生產過程中，冬季畜禽舍加熱取暖已經成為保障生產成績的必要條件。","zh-CN":"在畜禽养殖生产过程中，冬季畜禽舍加热取暖已经成为保障生产成绩的必要条件。","en":"In livestock production, heating animal housing in winter is essential for maintaining production performance.","th":"ในการผลิตปศุสัตว์ การให้ความอบอุ่นแก่โรงเรือนในฤดูหนาวเป็นปัจจัยสำคัญต่อประสิทธิภาพการผลิต"},{"zh":"在畜禽養殖生產過程中，冬季畜禽舍加熱取暖已經成為保障生產成績的必要條件。","zh-CN":"在畜禽养殖生产过程中，冬季畜禽舍加热取暖已经成为保障生产成绩的必要条件。","en":"In livestock production, heating animal housing in winter is essential for maintaining production performance.","th":"ในการผลิตปศุสัตว์ การให้ความอบอุ่นแก่โรงเรือนในฤดูหนาวเป็นปัจจัยสำคัญต่อประสิทธิภาพการผลิต"},{"zh":"傳統的加熱取暖模式包括熱風爐取暖、鍋爐取暖以及紅外線燈取暖等。但隨著國家政策變化（原則上不得新建10噸/時及以下的燃煤鍋爐）以及飼料成本和人工成本的提高，傳統的加熱取暖模式已經不能滿足生產需求，在這種情況下，一種高效、環保、節能的燃氣加熱器應運而生。","zh-CN":"传统的加热取暖模式包括热风炉取暖、锅炉取暖以及红外线灯取暖等。但随着国家政策变化（原则上不得新建10吨/时及以下的燃煤锅炉）以及饲料成本和人工成本的提高，传统的加热取暖模式已经不能满足生产需求，在这种情况下，一种高效、环保、节能的燃气加热器应运而生。","en":"Traditional systems include hot-air furnaces, boilers and infrared lamps. Policy changes and rising feed and labor costs created demand for efficient, cleaner and energy-saving gas heaters.","th":"ระบบแบบดั้งเดิมมีทั้งเตาลมร้อน หม้อไอน้ำ และหลอดอินฟราเรด การเปลี่ยนแปลงนโยบายรวมถึงต้นทุนอาหารสัตว์และแรงงานที่สูงขึ้น ทำให้เกิดความต้องการเครื่องทำความร้อนด้วยก๊าซที่มีประสิทธิภาพ สะอาด และประหยัดพลังงาน"},{"zh":"燃氣加熱器是一款以液化氣、天然氣或沼氣為燃料，在畜禽舍內進行加熱升溫、干燥的新型加熱設備。它的主要優點有：安全、高效、環保、自動化程度高、安裝方便、簡單易學。","zh-CN":"燃气加热器是一款以液化气、天然气或沼气为燃料，在畜禽舍内进行加热升温、干燥的新型加热设备。它的主要优点有：安全、高效、环保、自动化程度高、安装方便、简单易学。","en":"Gas heaters use LPG, natural gas or biogas to heat and dry livestock buildings. Their advantages include safety, efficiency, environmental performance, automation and easy installation.","th":"เครื่องทำความร้อนด้วยก๊าซใช้ LPG ก๊าซธรรมชาติ หรือก๊าซชีวภาพ เพื่อเพิ่มอุณหภูมิและลดความชื้นในโรงเรือน จุดเด่นคือปลอดภัย มีประสิทธิภาพ เป็นมิตรต่อสิ่งแวดล้อม ทำงานอัตโนมัติ และติดตั้งง่าย"},{"zh":"在畜禽養殖生產過程中，冬季畜禽舍加熱取暖已經成為保障生產成績的必要條件。","zh-CN":"在畜禽养殖生产过程中，冬季畜禽舍加热取暖已经成为保障生产成绩的必要条件。","en":"In livestock production, heating animal housing in winter is essential for maintaining production performance.","th":"ในการผลิตปศุสัตว์ การให้ความอบอุ่นแก่โรงเรือนในฤดูหนาวเป็นปัจจัยสำคัญต่อประสิทธิภาพการผลิต"},{"zh":"傳統的加熱取暖模式包括熱風爐取暖、鍋爐取暖以及紅外線燈取暖等。但隨著國家政策變化（原則上不得新建10噸/時及以下的燃煤鍋爐）以及飼料成本和人工成本的提高，傳統的加熱取暖模式已經不能滿足生產需求，在這種情況下，一種高效、環保、節能的燃氣加熱器應運而生。","zh-CN":"传统的加热取暖模式包括热风炉取暖、锅炉取暖以及红外线灯取暖等。但随着国家政策变化（原则上不得新建10吨/时及以下的燃煤锅炉）以及饲料成本和人工成本的提高，传统的加热取暖模式已经不能满足生产需求，在这种情况下，一种高效、环保、节能的燃气加热器应运而生。","en":"Traditional systems include hot-air furnaces, boilers and infrared lamps. Policy changes and rising feed and labor costs created demand for efficient, cleaner and energy-saving gas heaters.","th":"ระบบแบบดั้งเดิมมีทั้งเตาลมร้อน หม้อไอน้ำ และหลอดอินฟราเรด การเปลี่ยนแปลงนโยบายรวมถึงต้นทุนอาหารสัตว์และแรงงานที่สูงขึ้น ทำให้เกิดความต้องการเครื่องทำความร้อนด้วยก๊าซที่มีประสิทธิภาพ สะอาด และประหยัดพลังงาน"},{"zh":"燃氣加熱器是一款以液化氣、天然氣或沼氣為燃料，在畜禽舍內進行加熱升溫、干燥的新型加熱設備。它的主要優點有：安全、高效、環保、自動化程度高、安裝方便、簡單易學。","zh-CN":"燃气加热器是一款以液化气、天然气或沼气为燃料，在畜禽舍内进行加热升温、干燥的新型加热设备。它的主要优点有：安全、高效、环保、自动化程度高、安装方便、简单易学。","en":"Gas heaters use LPG, natural gas or biogas to heat and dry livestock buildings. Their advantages include safety, efficiency, environmental performance, automation and easy installation.","th":"เครื่องทำความร้อนด้วยก๊าซใช้ LPG ก๊าซธรรมชาติ หรือก๊าซชีวภาพ เพื่อเพิ่มอุณหภูมิและลดความชื้นในโรงเรือน จุดเด่นคือปลอดภัย มีประสิทธิภาพ เป็นมิตรต่อสิ่งแวดล้อม ทำงานอัตโนมัติ และติดตั้งง่าย"}]'::jsonb, '{"zh":"未註明","zh-CN":"未注明","en":"Source not specified","th":"ไม่ระบุแหล่งที่มา"}'::jsonb, 'hkfb16ff', 4477, '2016-09-05'::date, 1, true) on conflict (id) do update set title = excluded.title, summary = excluded.summary, body = excluded.body, source = excluded.source, author = excluded.author, views = excluded.views, published_at = excluded.published_at, sort_order = excluded.sort_order;
insert into public.hls_news (id, title, summary, body, source, author, views, published_at, sort_order, published) values (9, '{"zh":"廣東江門鶴山：加強水產養殖設備巡查 保障養殖戶用電安全","zh-CN":"广东江门鹤山：加强水产养殖设备巡查 保障养殖户用电安全","en":"Heshan, Jiangmen strengthens aquaculture equipment inspections and electrical safety","th":"เฮ่อซาน เมืองเจียงเหมิน เพิ่มการตรวจอุปกรณ์เพาะเลี้ยงสัตว์น้ำและความปลอดภัยทางไฟฟ้า"}'::jsonb, '{"zh":"在畜禽養殖生產中，冬季加熱與現代化設備對生產效率與管理具有重要影響。","zh-CN":"在畜禽养殖生产中，冬季加热与现代化设备对生产效率与管理具有重要影响。","en":"Winter heating and modern equipment can have an important impact on livestock productivity and operations.","th":"ระบบทำความร้อนในฤดูหนาวและอุปกรณ์สมัยใหม่มีผลสำคัญต่อประสิทธิภาพและการจัดการฟาร์มปศุสัตว์"}'::jsonb, '[{"zh":"在畜禽養殖生產過程中，冬季畜禽舍加熱取暖已經成為保障生產成績的必要條件。","zh-CN":"在畜禽养殖生产过程中，冬季畜禽舍加热取暖已经成为保障生产成绩的必要条件。","en":"In livestock production, heating animal housing in winter is essential for maintaining production performance.","th":"ในการผลิตปศุสัตว์ การให้ความอบอุ่นแก่โรงเรือนในฤดูหนาวเป็นปัจจัยสำคัญต่อประสิทธิภาพการผลิต"},{"zh":"在畜禽養殖生產過程中，冬季畜禽舍加熱取暖已經成為保障生產成績的必要條件。","zh-CN":"在畜禽养殖生产过程中，冬季畜禽舍加热取暖已经成为保障生产成绩的必要条件。","en":"In livestock production, heating animal housing in winter is essential for maintaining production performance.","th":"ในการผลิตปศุสัตว์ การให้ความอบอุ่นแก่โรงเรือนในฤดูหนาวเป็นปัจจัยสำคัญต่อประสิทธิภาพการผลิต"},{"zh":"傳統的加熱取暖模式包括熱風爐取暖、鍋爐取暖以及紅外線燈取暖等。但隨著國家政策變化（原則上不得新建10噸/時及以下的燃煤鍋爐）以及飼料成本和人工成本的提高，傳統的加熱取暖模式已經不能滿足生產需求，在這種情況下，一種高效、環保、節能的燃氣加熱器應運而生。","zh-CN":"传统的加热取暖模式包括热风炉取暖、锅炉取暖以及红外线灯取暖等。但随着国家政策变化（原则上不得新建10吨/时及以下的燃煤锅炉）以及饲料成本和人工成本的提高，传统的加热取暖模式已经不能满足生产需求，在这种情况下，一种高效、环保、节能的燃气加热器应运而生。","en":"Traditional systems include hot-air furnaces, boilers and infrared lamps. Policy changes and rising feed and labor costs created demand for efficient, cleaner and energy-saving gas heaters.","th":"ระบบแบบดั้งเดิมมีทั้งเตาลมร้อน หม้อไอน้ำ และหลอดอินฟราเรด การเปลี่ยนแปลงนโยบายรวมถึงต้นทุนอาหารสัตว์และแรงงานที่สูงขึ้น ทำให้เกิดความต้องการเครื่องทำความร้อนด้วยก๊าซที่มีประสิทธิภาพ สะอาด และประหยัดพลังงาน"},{"zh":"燃氣加熱器是一款以液化氣、天然氣或沼氣為燃料，在畜禽舍內進行加熱升溫、干燥的新型加熱設備。它的主要優點有：安全、高效、環保、自動化程度高、安裝方便、簡單易學。","zh-CN":"燃气加热器是一款以液化气、天然气或沼气为燃料，在畜禽舍内进行加热升温、干燥的新型加热设备。它的主要优点有：安全、高效、环保、自动化程度高、安装方便、简单易学。","en":"Gas heaters use LPG, natural gas or biogas to heat and dry livestock buildings. Their advantages include safety, efficiency, environmental performance, automation and easy installation.","th":"เครื่องทำความร้อนด้วยก๊าซใช้ LPG ก๊าซธรรมชาติ หรือก๊าซชีวภาพ เพื่อเพิ่มอุณหภูมิและลดความชื้นในโรงเรือน จุดเด่นคือปลอดภัย มีประสิทธิภาพ เป็นมิตรต่อสิ่งแวดล้อม ทำงานอัตโนมัติ และติดตั้งง่าย"},{"zh":"在畜禽養殖生產過程中，冬季畜禽舍加熱取暖已經成為保障生產成績的必要條件。","zh-CN":"在畜禽养殖生产过程中，冬季畜禽舍加热取暖已经成为保障生产成绩的必要条件。","en":"In livestock production, heating animal housing in winter is essential for maintaining production performance.","th":"ในการผลิตปศุสัตว์ การให้ความอบอุ่นแก่โรงเรือนในฤดูหนาวเป็นปัจจัยสำคัญต่อประสิทธิภาพการผลิต"},{"zh":"傳統的加熱取暖模式包括熱風爐取暖、鍋爐取暖以及紅外線燈取暖等。但隨著國家政策變化（原則上不得新建10噸/時及以下的燃煤鍋爐）以及飼料成本和人工成本的提高，傳統的加熱取暖模式已經不能滿足生產需求，在這種情況下，一種高效、環保、節能的燃氣加熱器應運而生。","zh-CN":"传统的加热取暖模式包括热风炉取暖、锅炉取暖以及红外线灯取暖等。但随着国家政策变化（原则上不得新建10吨/时及以下的燃煤锅炉）以及饲料成本和人工成本的提高，传统的加热取暖模式已经不能满足生产需求，在这种情况下，一种高效、环保、节能的燃气加热器应运而生。","en":"Traditional systems include hot-air furnaces, boilers and infrared lamps. Policy changes and rising feed and labor costs created demand for efficient, cleaner and energy-saving gas heaters.","th":"ระบบแบบดั้งเดิมมีทั้งเตาลมร้อน หม้อไอน้ำ และหลอดอินฟราเรด การเปลี่ยนแปลงนโยบายรวมถึงต้นทุนอาหารสัตว์และแรงงานที่สูงขึ้น ทำให้เกิดความต้องการเครื่องทำความร้อนด้วยก๊าซที่มีประสิทธิภาพ สะอาด และประหยัดพลังงาน"},{"zh":"燃氣加熱器是一款以液化氣、天然氣或沼氣為燃料，在畜禽舍內進行加熱升溫、干燥的新型加熱設備。它的主要優點有：安全、高效、環保、自動化程度高、安裝方便、簡單易學。","zh-CN":"燃气加热器是一款以液化气、天然气或沼气为燃料，在畜禽舍内进行加热升温、干燥的新型加热设备。它的主要优点有：安全、高效、环保、自动化程度高、安装方便、简单易学。","en":"Gas heaters use LPG, natural gas or biogas to heat and dry livestock buildings. Their advantages include safety, efficiency, environmental performance, automation and easy installation.","th":"เครื่องทำความร้อนด้วยก๊าซใช้ LPG ก๊าซธรรมชาติ หรือก๊าซชีวภาพ เพื่อเพิ่มอุณหภูมิและลดความชื้นในโรงเรือน จุดเด่นคือปลอดภัย มีประสิทธิภาพ เป็นมิตรต่อสิ่งแวดล้อม ทำงานอัตโนมัติ และติดตั้งง่าย"}]'::jsonb, '{"zh":"未註明","zh-CN":"未注明","en":"Source not specified","th":"ไม่ระบุแหล่งที่มา"}'::jsonb, 'hkfb16ff', 4438, '2016-09-05'::date, 2, true) on conflict (id) do update set title = excluded.title, summary = excluded.summary, body = excluded.body, source = excluded.source, author = excluded.author, views = excluded.views, published_at = excluded.published_at, sort_order = excluded.sort_order;
insert into public.hls_news (id, title, summary, body, source, author, views, published_at, sort_order, published) values (8, '{"zh":"現代化器械服務市民 荊門園林工人集中學習器械使用保養","zh-CN":"现代化器械服务市民 荆门园林工人集中学习器械使用保养","en":"Jingmen landscape crews train in modern equipment operation and maintenance","th":"เจ้าหน้าที่สวนเมืองจิงเหมินอบรมการใช้และบำรุงรักษาเครื่องจักรสมัยใหม่"}'::jsonb, '{"zh":"在畜禽養殖生產中，冬季加熱與現代化設備對生產效率與管理具有重要影響。","zh-CN":"在畜禽养殖生产中，冬季加热与现代化设备对生产效率与管理具有重要影响。","en":"Winter heating and modern equipment can have an important impact on livestock productivity and operations.","th":"ระบบทำความร้อนในฤดูหนาวและอุปกรณ์สมัยใหม่มีผลสำคัญต่อประสิทธิภาพและการจัดการฟาร์มปศุสัตว์"}'::jsonb, '[{"zh":"在畜禽養殖生產過程中，冬季畜禽舍加熱取暖已經成為保障生產成績的必要條件。","zh-CN":"在畜禽养殖生产过程中，冬季畜禽舍加热取暖已经成为保障生产成绩的必要条件。","en":"In livestock production, heating animal housing in winter is essential for maintaining production performance.","th":"ในการผลิตปศุสัตว์ การให้ความอบอุ่นแก่โรงเรือนในฤดูหนาวเป็นปัจจัยสำคัญต่อประสิทธิภาพการผลิต"},{"zh":"在畜禽養殖生產過程中，冬季畜禽舍加熱取暖已經成為保障生產成績的必要條件。","zh-CN":"在畜禽养殖生产过程中，冬季畜禽舍加热取暖已经成为保障生产成绩的必要条件。","en":"In livestock production, heating animal housing in winter is essential for maintaining production performance.","th":"ในการผลิตปศุสัตว์ การให้ความอบอุ่นแก่โรงเรือนในฤดูหนาวเป็นปัจจัยสำคัญต่อประสิทธิภาพการผลิต"},{"zh":"傳統的加熱取暖模式包括熱風爐取暖、鍋爐取暖以及紅外線燈取暖等。但隨著國家政策變化（原則上不得新建10噸/時及以下的燃煤鍋爐）以及飼料成本和人工成本的提高，傳統的加熱取暖模式已經不能滿足生產需求，在這種情況下，一種高效、環保、節能的燃氣加熱器應運而生。","zh-CN":"传统的加热取暖模式包括热风炉取暖、锅炉取暖以及红外线灯取暖等。但随着国家政策变化（原则上不得新建10吨/时及以下的燃煤锅炉）以及饲料成本和人工成本的提高，传统的加热取暖模式已经不能满足生产需求，在这种情况下，一种高效、环保、节能的燃气加热器应运而生。","en":"Traditional systems include hot-air furnaces, boilers and infrared lamps. Policy changes and rising feed and labor costs created demand for efficient, cleaner and energy-saving gas heaters.","th":"ระบบแบบดั้งเดิมมีทั้งเตาลมร้อน หม้อไอน้ำ และหลอดอินฟราเรด การเปลี่ยนแปลงนโยบายรวมถึงต้นทุนอาหารสัตว์และแรงงานที่สูงขึ้น ทำให้เกิดความต้องการเครื่องทำความร้อนด้วยก๊าซที่มีประสิทธิภาพ สะอาด และประหยัดพลังงาน"},{"zh":"燃氣加熱器是一款以液化氣、天然氣或沼氣為燃料，在畜禽舍內進行加熱升溫、干燥的新型加熱設備。它的主要優點有：安全、高效、環保、自動化程度高、安裝方便、簡單易學。","zh-CN":"燃气加热器是一款以液化气、天然气或沼气为燃料，在畜禽舍内进行加热升温、干燥的新型加热设备。它的主要优点有：安全、高效、环保、自动化程度高、安装方便、简单易学。","en":"Gas heaters use LPG, natural gas or biogas to heat and dry livestock buildings. Their advantages include safety, efficiency, environmental performance, automation and easy installation.","th":"เครื่องทำความร้อนด้วยก๊าซใช้ LPG ก๊าซธรรมชาติ หรือก๊าซชีวภาพ เพื่อเพิ่มอุณหภูมิและลดความชื้นในโรงเรือน จุดเด่นคือปลอดภัย มีประสิทธิภาพ เป็นมิตรต่อสิ่งแวดล้อม ทำงานอัตโนมัติ และติดตั้งง่าย"},{"zh":"在畜禽養殖生產過程中，冬季畜禽舍加熱取暖已經成為保障生產成績的必要條件。","zh-CN":"在畜禽养殖生产过程中，冬季畜禽舍加热取暖已经成为保障生产成绩的必要条件。","en":"In livestock production, heating animal housing in winter is essential for maintaining production performance.","th":"ในการผลิตปศุสัตว์ การให้ความอบอุ่นแก่โรงเรือนในฤดูหนาวเป็นปัจจัยสำคัญต่อประสิทธิภาพการผลิต"},{"zh":"傳統的加熱取暖模式包括熱風爐取暖、鍋爐取暖以及紅外線燈取暖等。但隨著國家政策變化（原則上不得新建10噸/時及以下的燃煤鍋爐）以及飼料成本和人工成本的提高，傳統的加熱取暖模式已經不能滿足生產需求，在這種情況下，一種高效、環保、節能的燃氣加熱器應運而生。","zh-CN":"传统的加热取暖模式包括热风炉取暖、锅炉取暖以及红外线灯取暖等。但随着国家政策变化（原则上不得新建10吨/时及以下的燃煤锅炉）以及饲料成本和人工成本的提高，传统的加热取暖模式已经不能满足生产需求，在这种情况下，一种高效、环保、节能的燃气加热器应运而生。","en":"Traditional systems include hot-air furnaces, boilers and infrared lamps. Policy changes and rising feed and labor costs created demand for efficient, cleaner and energy-saving gas heaters.","th":"ระบบแบบดั้งเดิมมีทั้งเตาลมร้อน หม้อไอน้ำ และหลอดอินฟราเรด การเปลี่ยนแปลงนโยบายรวมถึงต้นทุนอาหารสัตว์และแรงงานที่สูงขึ้น ทำให้เกิดความต้องการเครื่องทำความร้อนด้วยก๊าซที่มีประสิทธิภาพ สะอาด และประหยัดพลังงาน"},{"zh":"燃氣加熱器是一款以液化氣、天然氣或沼氣為燃料，在畜禽舍內進行加熱升溫、干燥的新型加熱設備。它的主要優點有：安全、高效、環保、自動化程度高、安裝方便、簡單易學。","zh-CN":"燃气加热器是一款以液化气、天然气或沼气为燃料，在畜禽舍内进行加热升温、干燥的新型加热设备。它的主要优点有：安全、高效、环保、自动化程度高、安装方便、简单易学。","en":"Gas heaters use LPG, natural gas or biogas to heat and dry livestock buildings. Their advantages include safety, efficiency, environmental performance, automation and easy installation.","th":"เครื่องทำความร้อนด้วยก๊าซใช้ LPG ก๊าซธรรมชาติ หรือก๊าซชีวภาพ เพื่อเพิ่มอุณหภูมิและลดความชื้นในโรงเรือน จุดเด่นคือปลอดภัย มีประสิทธิภาพ เป็นมิตรต่อสิ่งแวดล้อม ทำงานอัตโนมัติ และติดตั้งง่าย"}]'::jsonb, '{"zh":"未註明","zh-CN":"未注明","en":"Source not specified","th":"ไม่ระบุแหล่งที่มา"}'::jsonb, 'hkfb16ff', 3411, '2016-09-05'::date, 3, true) on conflict (id) do update set title = excluded.title, summary = excluded.summary, body = excluded.body, source = excluded.source, author = excluded.author, views = excluded.views, published_at = excluded.published_at, sort_order = excluded.sort_order;
insert into public.hls_news (id, title, summary, body, source, author, views, published_at, sort_order, published) values (7, '{"zh":"現代化養豬場自動化養豬設備的使用方法","zh-CN":"现代化养猪场自动化养猪设备的使用方法","en":"How to use automated equipment on a modern pig farm","th":"วิธีใช้อุปกรณ์อัตโนมัติในฟาร์มสุกรสมัยใหม่"}'::jsonb, '{"zh":"在畜禽養殖生產中，冬季加熱與現代化設備對生產效率與管理具有重要影響。","zh-CN":"在畜禽养殖生产中，冬季加热与现代化设备对生产效率与管理具有重要影响。","en":"Winter heating and modern equipment can have an important impact on livestock productivity and operations.","th":"ระบบทำความร้อนในฤดูหนาวและอุปกรณ์สมัยใหม่มีผลสำคัญต่อประสิทธิภาพและการจัดการฟาร์มปศุสัตว์"}'::jsonb, '[{"zh":"在畜禽養殖生產過程中，冬季畜禽舍加熱取暖已經成為保障生產成績的必要條件。","zh-CN":"在畜禽养殖生产过程中，冬季畜禽舍加热取暖已经成为保障生产成绩的必要条件。","en":"In livestock production, heating animal housing in winter is essential for maintaining production performance.","th":"ในการผลิตปศุสัตว์ การให้ความอบอุ่นแก่โรงเรือนในฤดูหนาวเป็นปัจจัยสำคัญต่อประสิทธิภาพการผลิต"},{"zh":"在畜禽養殖生產過程中，冬季畜禽舍加熱取暖已經成為保障生產成績的必要條件。","zh-CN":"在畜禽养殖生产过程中，冬季畜禽舍加热取暖已经成为保障生产成绩的必要条件。","en":"In livestock production, heating animal housing in winter is essential for maintaining production performance.","th":"ในการผลิตปศุสัตว์ การให้ความอบอุ่นแก่โรงเรือนในฤดูหนาวเป็นปัจจัยสำคัญต่อประสิทธิภาพการผลิต"},{"zh":"傳統的加熱取暖模式包括熱風爐取暖、鍋爐取暖以及紅外線燈取暖等。但隨著國家政策變化（原則上不得新建10噸/時及以下的燃煤鍋爐）以及飼料成本和人工成本的提高，傳統的加熱取暖模式已經不能滿足生產需求，在這種情況下，一種高效、環保、節能的燃氣加熱器應運而生。","zh-CN":"传统的加热取暖模式包括热风炉取暖、锅炉取暖以及红外线灯取暖等。但随着国家政策变化（原则上不得新建10吨/时及以下的燃煤锅炉）以及饲料成本和人工成本的提高，传统的加热取暖模式已经不能满足生产需求，在这种情况下，一种高效、环保、节能的燃气加热器应运而生。","en":"Traditional systems include hot-air furnaces, boilers and infrared lamps. Policy changes and rising feed and labor costs created demand for efficient, cleaner and energy-saving gas heaters.","th":"ระบบแบบดั้งเดิมมีทั้งเตาลมร้อน หม้อไอน้ำ และหลอดอินฟราเรด การเปลี่ยนแปลงนโยบายรวมถึงต้นทุนอาหารสัตว์และแรงงานที่สูงขึ้น ทำให้เกิดความต้องการเครื่องทำความร้อนด้วยก๊าซที่มีประสิทธิภาพ สะอาด และประหยัดพลังงาน"},{"zh":"燃氣加熱器是一款以液化氣、天然氣或沼氣為燃料，在畜禽舍內進行加熱升溫、干燥的新型加熱設備。它的主要優點有：安全、高效、環保、自動化程度高、安裝方便、簡單易學。","zh-CN":"燃气加热器是一款以液化气、天然气或沼气为燃料，在畜禽舍内进行加热升温、干燥的新型加热设备。它的主要优点有：安全、高效、环保、自动化程度高、安装方便、简单易学。","en":"Gas heaters use LPG, natural gas or biogas to heat and dry livestock buildings. Their advantages include safety, efficiency, environmental performance, automation and easy installation.","th":"เครื่องทำความร้อนด้วยก๊าซใช้ LPG ก๊าซธรรมชาติ หรือก๊าซชีวภาพ เพื่อเพิ่มอุณหภูมิและลดความชื้นในโรงเรือน จุดเด่นคือปลอดภัย มีประสิทธิภาพ เป็นมิตรต่อสิ่งแวดล้อม ทำงานอัตโนมัติ และติดตั้งง่าย"},{"zh":"在畜禽養殖生產過程中，冬季畜禽舍加熱取暖已經成為保障生產成績的必要條件。","zh-CN":"在畜禽养殖生产过程中，冬季畜禽舍加热取暖已经成为保障生产成绩的必要条件。","en":"In livestock production, heating animal housing in winter is essential for maintaining production performance.","th":"ในการผลิตปศุสัตว์ การให้ความอบอุ่นแก่โรงเรือนในฤดูหนาวเป็นปัจจัยสำคัญต่อประสิทธิภาพการผลิต"},{"zh":"傳統的加熱取暖模式包括熱風爐取暖、鍋爐取暖以及紅外線燈取暖等。但隨著國家政策變化（原則上不得新建10噸/時及以下的燃煤鍋爐）以及飼料成本和人工成本的提高，傳統的加熱取暖模式已經不能滿足生產需求，在這種情況下，一種高效、環保、節能的燃氣加熱器應運而生。","zh-CN":"传统的加热取暖模式包括热风炉取暖、锅炉取暖以及红外线灯取暖等。但随着国家政策变化（原则上不得新建10吨/时及以下的燃煤锅炉）以及饲料成本和人工成本的提高，传统的加热取暖模式已经不能满足生产需求，在这种情况下，一种高效、环保、节能的燃气加热器应运而生。","en":"Traditional systems include hot-air furnaces, boilers and infrared lamps. Policy changes and rising feed and labor costs created demand for efficient, cleaner and energy-saving gas heaters.","th":"ระบบแบบดั้งเดิมมีทั้งเตาลมร้อน หม้อไอน้ำ และหลอดอินฟราเรด การเปลี่ยนแปลงนโยบายรวมถึงต้นทุนอาหารสัตว์และแรงงานที่สูงขึ้น ทำให้เกิดความต้องการเครื่องทำความร้อนด้วยก๊าซที่มีประสิทธิภาพ สะอาด และประหยัดพลังงาน"},{"zh":"燃氣加熱器是一款以液化氣、天然氣或沼氣為燃料，在畜禽舍內進行加熱升溫、干燥的新型加熱設備。它的主要優點有：安全、高效、環保、自動化程度高、安裝方便、簡單易學。","zh-CN":"燃气加热器是一款以液化气、天然气或沼气为燃料，在畜禽舍内进行加热升温、干燥的新型加热设备。它的主要优点有：安全、高效、环保、自动化程度高、安装方便、简单易学。","en":"Gas heaters use LPG, natural gas or biogas to heat and dry livestock buildings. Their advantages include safety, efficiency, environmental performance, automation and easy installation.","th":"เครื่องทำความร้อนด้วยก๊าซใช้ LPG ก๊าซธรรมชาติ หรือก๊าซชีวภาพ เพื่อเพิ่มอุณหภูมิและลดความชื้นในโรงเรือน จุดเด่นคือปลอดภัย มีประสิทธิภาพ เป็นมิตรต่อสิ่งแวดล้อม ทำงานอัตโนมัติ และติดตั้งง่าย"}]'::jsonb, '{"zh":"未註明","zh-CN":"未注明","en":"Source not specified","th":"ไม่ระบุแหล่งที่มา"}'::jsonb, 'hkfb16ff', 3569, '2016-09-05'::date, 4, true) on conflict (id) do update set title = excluded.title, summary = excluded.summary, body = excluded.body, source = excluded.source, author = excluded.author, views = excluded.views, published_at = excluded.published_at, sort_order = excluded.sort_order;
insert into public.hls_news (id, title, summary, body, source, author, views, published_at, sort_order, published) values (6, '{"zh":"現代化養豬設備對養豬生產的影響（1）","zh-CN":"现代化养猪设备对养猪生产的影响（1）","en":"The impact of modern equipment on pig production (1)","th":"ผลของอุปกรณ์สมัยใหม่ต่อการผลิตสุกร (1)"}'::jsonb, '{"zh":"在畜禽養殖生產中，冬季加熱與現代化設備對生產效率與管理具有重要影響。","zh-CN":"在畜禽养殖生产中，冬季加热与现代化设备对生产效率与管理具有重要影响。","en":"Winter heating and modern equipment can have an important impact on livestock productivity and operations.","th":"ระบบทำความร้อนในฤดูหนาวและอุปกรณ์สมัยใหม่มีผลสำคัญต่อประสิทธิภาพและการจัดการฟาร์มปศุสัตว์"}'::jsonb, '[{"zh":"在畜禽養殖生產過程中，冬季畜禽舍加熱取暖已經成為保障生產成績的必要條件。","zh-CN":"在畜禽养殖生产过程中，冬季畜禽舍加热取暖已经成为保障生产成绩的必要条件。","en":"In livestock production, heating animal housing in winter is essential for maintaining production performance.","th":"ในการผลิตปศุสัตว์ การให้ความอบอุ่นแก่โรงเรือนในฤดูหนาวเป็นปัจจัยสำคัญต่อประสิทธิภาพการผลิต"},{"zh":"在畜禽養殖生產過程中，冬季畜禽舍加熱取暖已經成為保障生產成績的必要條件。","zh-CN":"在畜禽养殖生产过程中，冬季畜禽舍加热取暖已经成为保障生产成绩的必要条件。","en":"In livestock production, heating animal housing in winter is essential for maintaining production performance.","th":"ในการผลิตปศุสัตว์ การให้ความอบอุ่นแก่โรงเรือนในฤดูหนาวเป็นปัจจัยสำคัญต่อประสิทธิภาพการผลิต"},{"zh":"傳統的加熱取暖模式包括熱風爐取暖、鍋爐取暖以及紅外線燈取暖等。但隨著國家政策變化（原則上不得新建10噸/時及以下的燃煤鍋爐）以及飼料成本和人工成本的提高，傳統的加熱取暖模式已經不能滿足生產需求，在這種情況下，一種高效、環保、節能的燃氣加熱器應運而生。","zh-CN":"传统的加热取暖模式包括热风炉取暖、锅炉取暖以及红外线灯取暖等。但随着国家政策变化（原则上不得新建10吨/时及以下的燃煤锅炉）以及饲料成本和人工成本的提高，传统的加热取暖模式已经不能满足生产需求，在这种情况下，一种高效、环保、节能的燃气加热器应运而生。","en":"Traditional systems include hot-air furnaces, boilers and infrared lamps. Policy changes and rising feed and labor costs created demand for efficient, cleaner and energy-saving gas heaters.","th":"ระบบแบบดั้งเดิมมีทั้งเตาลมร้อน หม้อไอน้ำ และหลอดอินฟราเรด การเปลี่ยนแปลงนโยบายรวมถึงต้นทุนอาหารสัตว์และแรงงานที่สูงขึ้น ทำให้เกิดความต้องการเครื่องทำความร้อนด้วยก๊าซที่มีประสิทธิภาพ สะอาด และประหยัดพลังงาน"},{"zh":"燃氣加熱器是一款以液化氣、天然氣或沼氣為燃料，在畜禽舍內進行加熱升溫、干燥的新型加熱設備。它的主要優點有：安全、高效、環保、自動化程度高、安裝方便、簡單易學。","zh-CN":"燃气加热器是一款以液化气、天然气或沼气为燃料，在畜禽舍内进行加热升温、干燥的新型加热设备。它的主要优点有：安全、高效、环保、自动化程度高、安装方便、简单易学。","en":"Gas heaters use LPG, natural gas or biogas to heat and dry livestock buildings. Their advantages include safety, efficiency, environmental performance, automation and easy installation.","th":"เครื่องทำความร้อนด้วยก๊าซใช้ LPG ก๊าซธรรมชาติ หรือก๊าซชีวภาพ เพื่อเพิ่มอุณหภูมิและลดความชื้นในโรงเรือน จุดเด่นคือปลอดภัย มีประสิทธิภาพ เป็นมิตรต่อสิ่งแวดล้อม ทำงานอัตโนมัติ และติดตั้งง่าย"},{"zh":"在畜禽養殖生產過程中，冬季畜禽舍加熱取暖已經成為保障生產成績的必要條件。","zh-CN":"在畜禽养殖生产过程中，冬季畜禽舍加热取暖已经成为保障生产成绩的必要条件。","en":"In livestock production, heating animal housing in winter is essential for maintaining production performance.","th":"ในการผลิตปศุสัตว์ การให้ความอบอุ่นแก่โรงเรือนในฤดูหนาวเป็นปัจจัยสำคัญต่อประสิทธิภาพการผลิต"},{"zh":"傳統的加熱取暖模式包括熱風爐取暖、鍋爐取暖以及紅外線燈取暖等。但隨著國家政策變化（原則上不得新建10噸/時及以下的燃煤鍋爐）以及飼料成本和人工成本的提高，傳統的加熱取暖模式已經不能滿足生產需求，在這種情況下，一種高效、環保、節能的燃氣加熱器應運而生。","zh-CN":"传统的加热取暖模式包括热风炉取暖、锅炉取暖以及红外线灯取暖等。但随着国家政策变化（原则上不得新建10吨/时及以下的燃煤锅炉）以及饲料成本和人工成本的提高，传统的加热取暖模式已经不能满足生产需求，在这种情况下，一种高效、环保、节能的燃气加热器应运而生。","en":"Traditional systems include hot-air furnaces, boilers and infrared lamps. Policy changes and rising feed and labor costs created demand for efficient, cleaner and energy-saving gas heaters.","th":"ระบบแบบดั้งเดิมมีทั้งเตาลมร้อน หม้อไอน้ำ และหลอดอินฟราเรด การเปลี่ยนแปลงนโยบายรวมถึงต้นทุนอาหารสัตว์และแรงงานที่สูงขึ้น ทำให้เกิดความต้องการเครื่องทำความร้อนด้วยก๊าซที่มีประสิทธิภาพ สะอาด และประหยัดพลังงาน"},{"zh":"燃氣加熱器是一款以液化氣、天然氣或沼氣為燃料，在畜禽舍內進行加熱升溫、干燥的新型加熱設備。它的主要優點有：安全、高效、環保、自動化程度高、安裝方便、簡單易學。","zh-CN":"燃气加热器是一款以液化气、天然气或沼气为燃料，在畜禽舍内进行加热升温、干燥的新型加热设备。它的主要优点有：安全、高效、环保、自动化程度高、安装方便、简单易学。","en":"Gas heaters use LPG, natural gas or biogas to heat and dry livestock buildings. Their advantages include safety, efficiency, environmental performance, automation and easy installation.","th":"เครื่องทำความร้อนด้วยก๊าซใช้ LPG ก๊าซธรรมชาติ หรือก๊าซชีวภาพ เพื่อเพิ่มอุณหภูมิและลดความชื้นในโรงเรือน จุดเด่นคือปลอดภัย มีประสิทธิภาพ เป็นมิตรต่อสิ่งแวดล้อม ทำงานอัตโนมัติ และติดตั้งง่าย"}]'::jsonb, '{"zh":"未註明","zh-CN":"未注明","en":"Source not specified","th":"ไม่ระบุแหล่งที่มา"}'::jsonb, 'hkfb16ff', 3378, '2016-09-05'::date, 5, true) on conflict (id) do update set title = excluded.title, summary = excluded.summary, body = excluded.body, source = excluded.source, author = excluded.author, views = excluded.views, published_at = excluded.published_at, sort_order = excluded.sort_order;
insert into public.hls_news (id, title, summary, body, source, author, views, published_at, sort_order, published) values (5, '{"zh":"現代化養豬設備對養豬生產的影響：更科學 更環保","zh-CN":"现代化养猪设备对养猪生产的影响：更科学 更环保","en":"How modern pig-farming equipment improves science and sustainability","th":"อุปกรณ์ฟาร์มสุกรสมัยใหม่ช่วยเพิ่มความเป็นวิทยาศาสตร์และความยั่งยืน"}'::jsonb, '{"zh":"在畜禽養殖生產中，冬季加熱與現代化設備對生產效率與管理具有重要影響。","zh-CN":"在畜禽养殖生产中，冬季加热与现代化设备对生产效率与管理具有重要影响。","en":"Winter heating and modern equipment can have an important impact on livestock productivity and operations.","th":"ระบบทำความร้อนในฤดูหนาวและอุปกรณ์สมัยใหม่มีผลสำคัญต่อประสิทธิภาพและการจัดการฟาร์มปศุสัตว์"}'::jsonb, '[{"zh":"在畜禽養殖生產過程中，冬季畜禽舍加熱取暖已經成為保障生產成績的必要條件。","zh-CN":"在畜禽养殖生产过程中，冬季畜禽舍加热取暖已经成为保障生产成绩的必要条件。","en":"In livestock production, heating animal housing in winter is essential for maintaining production performance.","th":"ในการผลิตปศุสัตว์ การให้ความอบอุ่นแก่โรงเรือนในฤดูหนาวเป็นปัจจัยสำคัญต่อประสิทธิภาพการผลิต"},{"zh":"在畜禽養殖生產過程中，冬季畜禽舍加熱取暖已經成為保障生產成績的必要條件。","zh-CN":"在畜禽养殖生产过程中，冬季畜禽舍加热取暖已经成为保障生产成绩的必要条件。","en":"In livestock production, heating animal housing in winter is essential for maintaining production performance.","th":"ในการผลิตปศุสัตว์ การให้ความอบอุ่นแก่โรงเรือนในฤดูหนาวเป็นปัจจัยสำคัญต่อประสิทธิภาพการผลิต"},{"zh":"傳統的加熱取暖模式包括熱風爐取暖、鍋爐取暖以及紅外線燈取暖等。但隨著國家政策變化（原則上不得新建10噸/時及以下的燃煤鍋爐）以及飼料成本和人工成本的提高，傳統的加熱取暖模式已經不能滿足生產需求，在這種情況下，一種高效、環保、節能的燃氣加熱器應運而生。","zh-CN":"传统的加热取暖模式包括热风炉取暖、锅炉取暖以及红外线灯取暖等。但随着国家政策变化（原则上不得新建10吨/时及以下的燃煤锅炉）以及饲料成本和人工成本的提高，传统的加热取暖模式已经不能满足生产需求，在这种情况下，一种高效、环保、节能的燃气加热器应运而生。","en":"Traditional systems include hot-air furnaces, boilers and infrared lamps. Policy changes and rising feed and labor costs created demand for efficient, cleaner and energy-saving gas heaters.","th":"ระบบแบบดั้งเดิมมีทั้งเตาลมร้อน หม้อไอน้ำ และหลอดอินฟราเรด การเปลี่ยนแปลงนโยบายรวมถึงต้นทุนอาหารสัตว์และแรงงานที่สูงขึ้น ทำให้เกิดความต้องการเครื่องทำความร้อนด้วยก๊าซที่มีประสิทธิภาพ สะอาด และประหยัดพลังงาน"},{"zh":"燃氣加熱器是一款以液化氣、天然氣或沼氣為燃料，在畜禽舍內進行加熱升溫、干燥的新型加熱設備。它的主要優點有：安全、高效、環保、自動化程度高、安裝方便、簡單易學。","zh-CN":"燃气加热器是一款以液化气、天然气或沼气为燃料，在畜禽舍内进行加热升温、干燥的新型加热设备。它的主要优点有：安全、高效、环保、自动化程度高、安装方便、简单易学。","en":"Gas heaters use LPG, natural gas or biogas to heat and dry livestock buildings. Their advantages include safety, efficiency, environmental performance, automation and easy installation.","th":"เครื่องทำความร้อนด้วยก๊าซใช้ LPG ก๊าซธรรมชาติ หรือก๊าซชีวภาพ เพื่อเพิ่มอุณหภูมิและลดความชื้นในโรงเรือน จุดเด่นคือปลอดภัย มีประสิทธิภาพ เป็นมิตรต่อสิ่งแวดล้อม ทำงานอัตโนมัติ และติดตั้งง่าย"},{"zh":"在畜禽養殖生產過程中，冬季畜禽舍加熱取暖已經成為保障生產成績的必要條件。","zh-CN":"在畜禽养殖生产过程中，冬季畜禽舍加热取暖已经成为保障生产成绩的必要条件。","en":"In livestock production, heating animal housing in winter is essential for maintaining production performance.","th":"ในการผลิตปศุสัตว์ การให้ความอบอุ่นแก่โรงเรือนในฤดูหนาวเป็นปัจจัยสำคัญต่อประสิทธิภาพการผลิต"},{"zh":"傳統的加熱取暖模式包括熱風爐取暖、鍋爐取暖以及紅外線燈取暖等。但隨著國家政策變化（原則上不得新建10噸/時及以下的燃煤鍋爐）以及飼料成本和人工成本的提高，傳統的加熱取暖模式已經不能滿足生產需求，在這種情況下，一種高效、環保、節能的燃氣加熱器應運而生。","zh-CN":"传统的加热取暖模式包括热风炉取暖、锅炉取暖以及红外线灯取暖等。但随着国家政策变化（原则上不得新建10吨/时及以下的燃煤锅炉）以及饲料成本和人工成本的提高，传统的加热取暖模式已经不能满足生产需求，在这种情况下，一种高效、环保、节能的燃气加热器应运而生。","en":"Traditional systems include hot-air furnaces, boilers and infrared lamps. Policy changes and rising feed and labor costs created demand for efficient, cleaner and energy-saving gas heaters.","th":"ระบบแบบดั้งเดิมมีทั้งเตาลมร้อน หม้อไอน้ำ และหลอดอินฟราเรด การเปลี่ยนแปลงนโยบายรวมถึงต้นทุนอาหารสัตว์และแรงงานที่สูงขึ้น ทำให้เกิดความต้องการเครื่องทำความร้อนด้วยก๊าซที่มีประสิทธิภาพ สะอาด และประหยัดพลังงาน"},{"zh":"燃氣加熱器是一款以液化氣、天然氣或沼氣為燃料，在畜禽舍內進行加熱升溫、干燥的新型加熱設備。它的主要優點有：安全、高效、環保、自動化程度高、安裝方便、簡單易學。","zh-CN":"燃气加热器是一款以液化气、天然气或沼气为燃料，在畜禽舍内进行加热升温、干燥的新型加热设备。它的主要优点有：安全、高效、环保、自动化程度高、安装方便、简单易学。","en":"Gas heaters use LPG, natural gas or biogas to heat and dry livestock buildings. Their advantages include safety, efficiency, environmental performance, automation and easy installation.","th":"เครื่องทำความร้อนด้วยก๊าซใช้ LPG ก๊าซธรรมชาติ หรือก๊าซชีวภาพ เพื่อเพิ่มอุณหภูมิและลดความชื้นในโรงเรือน จุดเด่นคือปลอดภัย มีประสิทธิภาพ เป็นมิตรต่อสิ่งแวดล้อม ทำงานอัตโนมัติ และติดตั้งง่าย"}]'::jsonb, '{"zh":"未註明","zh-CN":"未注明","en":"Source not specified","th":"ไม่ระบุแหล่งที่มา"}'::jsonb, 'hkfb16ff', 3451, '2016-09-05'::date, 6, true) on conflict (id) do update set title = excluded.title, summary = excluded.summary, body = excluded.body, source = excluded.source, author = excluded.author, views = excluded.views, published_at = excluded.published_at, sort_order = excluded.sort_order;
insert into public.hls_news (id, title, summary, body, source, author, views, published_at, sort_order, published) values (4, '{"zh":"現代化養殖設備：鮑魚“別墅”","zh-CN":"现代化养殖设备：鲍鱼“别墅”","en":"Modern aquaculture equipment: abalone villas","th":"อุปกรณ์เพาะเลี้ยงสัตว์น้ำสมัยใหม่: บ้านเป๋าฮื้อ"}'::jsonb, '{"zh":"在畜禽養殖生產中，冬季加熱與現代化設備對生產效率與管理具有重要影響。","zh-CN":"在畜禽养殖生产中，冬季加热与现代化设备对生产效率与管理具有重要影响。","en":"Winter heating and modern equipment can have an important impact on livestock productivity and operations.","th":"ระบบทำความร้อนในฤดูหนาวและอุปกรณ์สมัยใหม่มีผลสำคัญต่อประสิทธิภาพและการจัดการฟาร์มปศุสัตว์"}'::jsonb, '[{"zh":"在畜禽養殖生產過程中，冬季畜禽舍加熱取暖已經成為保障生產成績的必要條件。","zh-CN":"在畜禽养殖生产过程中，冬季畜禽舍加热取暖已经成为保障生产成绩的必要条件。","en":"In livestock production, heating animal housing in winter is essential for maintaining production performance.","th":"ในการผลิตปศุสัตว์ การให้ความอบอุ่นแก่โรงเรือนในฤดูหนาวเป็นปัจจัยสำคัญต่อประสิทธิภาพการผลิต"},{"zh":"在畜禽養殖生產過程中，冬季畜禽舍加熱取暖已經成為保障生產成績的必要條件。","zh-CN":"在畜禽养殖生产过程中，冬季畜禽舍加热取暖已经成为保障生产成绩的必要条件。","en":"In livestock production, heating animal housing in winter is essential for maintaining production performance.","th":"ในการผลิตปศุสัตว์ การให้ความอบอุ่นแก่โรงเรือนในฤดูหนาวเป็นปัจจัยสำคัญต่อประสิทธิภาพการผลิต"},{"zh":"傳統的加熱取暖模式包括熱風爐取暖、鍋爐取暖以及紅外線燈取暖等。但隨著國家政策變化（原則上不得新建10噸/時及以下的燃煤鍋爐）以及飼料成本和人工成本的提高，傳統的加熱取暖模式已經不能滿足生產需求，在這種情況下，一種高效、環保、節能的燃氣加熱器應運而生。","zh-CN":"传统的加热取暖模式包括热风炉取暖、锅炉取暖以及红外线灯取暖等。但随着国家政策变化（原则上不得新建10吨/时及以下的燃煤锅炉）以及饲料成本和人工成本的提高，传统的加热取暖模式已经不能满足生产需求，在这种情况下，一种高效、环保、节能的燃气加热器应运而生。","en":"Traditional systems include hot-air furnaces, boilers and infrared lamps. Policy changes and rising feed and labor costs created demand for efficient, cleaner and energy-saving gas heaters.","th":"ระบบแบบดั้งเดิมมีทั้งเตาลมร้อน หม้อไอน้ำ และหลอดอินฟราเรด การเปลี่ยนแปลงนโยบายรวมถึงต้นทุนอาหารสัตว์และแรงงานที่สูงขึ้น ทำให้เกิดความต้องการเครื่องทำความร้อนด้วยก๊าซที่มีประสิทธิภาพ สะอาด และประหยัดพลังงาน"},{"zh":"燃氣加熱器是一款以液化氣、天然氣或沼氣為燃料，在畜禽舍內進行加熱升溫、干燥的新型加熱設備。它的主要優點有：安全、高效、環保、自動化程度高、安裝方便、簡單易學。","zh-CN":"燃气加热器是一款以液化气、天然气或沼气为燃料，在畜禽舍内进行加热升温、干燥的新型加热设备。它的主要优点有：安全、高效、环保、自动化程度高、安装方便、简单易学。","en":"Gas heaters use LPG, natural gas or biogas to heat and dry livestock buildings. Their advantages include safety, efficiency, environmental performance, automation and easy installation.","th":"เครื่องทำความร้อนด้วยก๊าซใช้ LPG ก๊าซธรรมชาติ หรือก๊าซชีวภาพ เพื่อเพิ่มอุณหภูมิและลดความชื้นในโรงเรือน จุดเด่นคือปลอดภัย มีประสิทธิภาพ เป็นมิตรต่อสิ่งแวดล้อม ทำงานอัตโนมัติ และติดตั้งง่าย"},{"zh":"在畜禽養殖生產過程中，冬季畜禽舍加熱取暖已經成為保障生產成績的必要條件。","zh-CN":"在畜禽养殖生产过程中，冬季畜禽舍加热取暖已经成为保障生产成绩的必要条件。","en":"In livestock production, heating animal housing in winter is essential for maintaining production performance.","th":"ในการผลิตปศุสัตว์ การให้ความอบอุ่นแก่โรงเรือนในฤดูหนาวเป็นปัจจัยสำคัญต่อประสิทธิภาพการผลิต"},{"zh":"傳統的加熱取暖模式包括熱風爐取暖、鍋爐取暖以及紅外線燈取暖等。但隨著國家政策變化（原則上不得新建10噸/時及以下的燃煤鍋爐）以及飼料成本和人工成本的提高，傳統的加熱取暖模式已經不能滿足生產需求，在這種情況下，一種高效、環保、節能的燃氣加熱器應運而生。","zh-CN":"传统的加热取暖模式包括热风炉取暖、锅炉取暖以及红外线灯取暖等。但随着国家政策变化（原则上不得新建10吨/时及以下的燃煤锅炉）以及饲料成本和人工成本的提高，传统的加热取暖模式已经不能满足生产需求，在这种情况下，一种高效、环保、节能的燃气加热器应运而生。","en":"Traditional systems include hot-air furnaces, boilers and infrared lamps. Policy changes and rising feed and labor costs created demand for efficient, cleaner and energy-saving gas heaters.","th":"ระบบแบบดั้งเดิมมีทั้งเตาลมร้อน หม้อไอน้ำ และหลอดอินฟราเรด การเปลี่ยนแปลงนโยบายรวมถึงต้นทุนอาหารสัตว์และแรงงานที่สูงขึ้น ทำให้เกิดความต้องการเครื่องทำความร้อนด้วยก๊าซที่มีประสิทธิภาพ สะอาด และประหยัดพลังงาน"},{"zh":"燃氣加熱器是一款以液化氣、天然氣或沼氣為燃料，在畜禽舍內進行加熱升溫、干燥的新型加熱設備。它的主要優點有：安全、高效、環保、自動化程度高、安裝方便、簡單易學。","zh-CN":"燃气加热器是一款以液化气、天然气或沼气为燃料，在畜禽舍内进行加热升温、干燥的新型加热设备。它的主要优点有：安全、高效、环保、自动化程度高、安装方便、简单易学。","en":"Gas heaters use LPG, natural gas or biogas to heat and dry livestock buildings. Their advantages include safety, efficiency, environmental performance, automation and easy installation.","th":"เครื่องทำความร้อนด้วยก๊าซใช้ LPG ก๊าซธรรมชาติ หรือก๊าซชีวภาพ เพื่อเพิ่มอุณหภูมิและลดความชื้นในโรงเรือน จุดเด่นคือปลอดภัย มีประสิทธิภาพ เป็นมิตรต่อสิ่งแวดล้อม ทำงานอัตโนมัติ และติดตั้งง่าย"}]'::jsonb, '{"zh":"未註明","zh-CN":"未注明","en":"Source not specified","th":"ไม่ระบุแหล่งที่มา"}'::jsonb, 'hkfb16ff', 3514, '2016-09-05'::date, 7, true) on conflict (id) do update set title = excluded.title, summary = excluded.summary, body = excluded.body, source = excluded.source, author = excluded.author, views = excluded.views, published_at = excluded.published_at, sort_order = excluded.sort_order;
insert into public.hls_news (id, title, summary, body, source, author, views, published_at, sort_order, published) values (3, '{"zh":"傳統養殖設備和現代化設備比較之通風系統","zh-CN":"传统养殖设备和现代化设备比较之通风系统","en":"Traditional and modern livestock equipment: ventilation systems","th":"เปรียบเทียบอุปกรณ์ปศุสัตว์แบบดั้งเดิมและสมัยใหม่: ระบบระบายอากาศ"}'::jsonb, '{"zh":"在畜禽養殖生產中，冬季加熱與現代化設備對生產效率與管理具有重要影響。","zh-CN":"在畜禽养殖生产中，冬季加热与现代化设备对生产效率与管理具有重要影响。","en":"Winter heating and modern equipment can have an important impact on livestock productivity and operations.","th":"ระบบทำความร้อนในฤดูหนาวและอุปกรณ์สมัยใหม่มีผลสำคัญต่อประสิทธิภาพและการจัดการฟาร์มปศุสัตว์"}'::jsonb, '[{"zh":"在畜禽養殖生產過程中，冬季畜禽舍加熱取暖已經成為保障生產成績的必要條件。","zh-CN":"在畜禽养殖生产过程中，冬季畜禽舍加热取暖已经成为保障生产成绩的必要条件。","en":"In livestock production, heating animal housing in winter is essential for maintaining production performance.","th":"ในการผลิตปศุสัตว์ การให้ความอบอุ่นแก่โรงเรือนในฤดูหนาวเป็นปัจจัยสำคัญต่อประสิทธิภาพการผลิต"},{"zh":"在畜禽養殖生產過程中，冬季畜禽舍加熱取暖已經成為保障生產成績的必要條件。","zh-CN":"在畜禽养殖生产过程中，冬季畜禽舍加热取暖已经成为保障生产成绩的必要条件。","en":"In livestock production, heating animal housing in winter is essential for maintaining production performance.","th":"ในการผลิตปศุสัตว์ การให้ความอบอุ่นแก่โรงเรือนในฤดูหนาวเป็นปัจจัยสำคัญต่อประสิทธิภาพการผลิต"},{"zh":"傳統的加熱取暖模式包括熱風爐取暖、鍋爐取暖以及紅外線燈取暖等。但隨著國家政策變化（原則上不得新建10噸/時及以下的燃煤鍋爐）以及飼料成本和人工成本的提高，傳統的加熱取暖模式已經不能滿足生產需求，在這種情況下，一種高效、環保、節能的燃氣加熱器應運而生。","zh-CN":"传统的加热取暖模式包括热风炉取暖、锅炉取暖以及红外线灯取暖等。但随着国家政策变化（原则上不得新建10吨/时及以下的燃煤锅炉）以及饲料成本和人工成本的提高，传统的加热取暖模式已经不能满足生产需求，在这种情况下，一种高效、环保、节能的燃气加热器应运而生。","en":"Traditional systems include hot-air furnaces, boilers and infrared lamps. Policy changes and rising feed and labor costs created demand for efficient, cleaner and energy-saving gas heaters.","th":"ระบบแบบดั้งเดิมมีทั้งเตาลมร้อน หม้อไอน้ำ และหลอดอินฟราเรด การเปลี่ยนแปลงนโยบายรวมถึงต้นทุนอาหารสัตว์และแรงงานที่สูงขึ้น ทำให้เกิดความต้องการเครื่องทำความร้อนด้วยก๊าซที่มีประสิทธิภาพ สะอาด และประหยัดพลังงาน"},{"zh":"燃氣加熱器是一款以液化氣、天然氣或沼氣為燃料，在畜禽舍內進行加熱升溫、干燥的新型加熱設備。它的主要優點有：安全、高效、環保、自動化程度高、安裝方便、簡單易學。","zh-CN":"燃气加热器是一款以液化气、天然气或沼气为燃料，在畜禽舍内进行加热升温、干燥的新型加热设备。它的主要优点有：安全、高效、环保、自动化程度高、安装方便、简单易学。","en":"Gas heaters use LPG, natural gas or biogas to heat and dry livestock buildings. Their advantages include safety, efficiency, environmental performance, automation and easy installation.","th":"เครื่องทำความร้อนด้วยก๊าซใช้ LPG ก๊าซธรรมชาติ หรือก๊าซชีวภาพ เพื่อเพิ่มอุณหภูมิและลดความชื้นในโรงเรือน จุดเด่นคือปลอดภัย มีประสิทธิภาพ เป็นมิตรต่อสิ่งแวดล้อม ทำงานอัตโนมัติ และติดตั้งง่าย"},{"zh":"在畜禽養殖生產過程中，冬季畜禽舍加熱取暖已經成為保障生產成績的必要條件。","zh-CN":"在畜禽养殖生产过程中，冬季畜禽舍加热取暖已经成为保障生产成绩的必要条件。","en":"In livestock production, heating animal housing in winter is essential for maintaining production performance.","th":"ในการผลิตปศุสัตว์ การให้ความอบอุ่นแก่โรงเรือนในฤดูหนาวเป็นปัจจัยสำคัญต่อประสิทธิภาพการผลิต"},{"zh":"傳統的加熱取暖模式包括熱風爐取暖、鍋爐取暖以及紅外線燈取暖等。但隨著國家政策變化（原則上不得新建10噸/時及以下的燃煤鍋爐）以及飼料成本和人工成本的提高，傳統的加熱取暖模式已經不能滿足生產需求，在這種情況下，一種高效、環保、節能的燃氣加熱器應運而生。","zh-CN":"传统的加热取暖模式包括热风炉取暖、锅炉取暖以及红外线灯取暖等。但随着国家政策变化（原则上不得新建10吨/时及以下的燃煤锅炉）以及饲料成本和人工成本的提高，传统的加热取暖模式已经不能满足生产需求，在这种情况下，一种高效、环保、节能的燃气加热器应运而生。","en":"Traditional systems include hot-air furnaces, boilers and infrared lamps. Policy changes and rising feed and labor costs created demand for efficient, cleaner and energy-saving gas heaters.","th":"ระบบแบบดั้งเดิมมีทั้งเตาลมร้อน หม้อไอน้ำ และหลอดอินฟราเรด การเปลี่ยนแปลงนโยบายรวมถึงต้นทุนอาหารสัตว์และแรงงานที่สูงขึ้น ทำให้เกิดความต้องการเครื่องทำความร้อนด้วยก๊าซที่มีประสิทธิภาพ สะอาด และประหยัดพลังงาน"},{"zh":"燃氣加熱器是一款以液化氣、天然氣或沼氣為燃料，在畜禽舍內進行加熱升溫、干燥的新型加熱設備。它的主要優點有：安全、高效、環保、自動化程度高、安裝方便、簡單易學。","zh-CN":"燃气加热器是一款以液化气、天然气或沼气为燃料，在畜禽舍内进行加热升温、干燥的新型加热设备。它的主要优点有：安全、高效、环保、自动化程度高、安装方便、简单易学。","en":"Gas heaters use LPG, natural gas or biogas to heat and dry livestock buildings. Their advantages include safety, efficiency, environmental performance, automation and easy installation.","th":"เครื่องทำความร้อนด้วยก๊าซใช้ LPG ก๊าซธรรมชาติ หรือก๊าซชีวภาพ เพื่อเพิ่มอุณหภูมิและลดความชื้นในโรงเรือน จุดเด่นคือปลอดภัย มีประสิทธิภาพ เป็นมิตรต่อสิ่งแวดล้อม ทำงานอัตโนมัติ และติดตั้งง่าย"}]'::jsonb, '{"zh":"未註明","zh-CN":"未注明","en":"Source not specified","th":"ไม่ระบุแหล่งที่มา"}'::jsonb, 'hkfb16ff', 3418, '2016-09-05'::date, 8, true) on conflict (id) do update set title = excluded.title, summary = excluded.summary, body = excluded.body, source = excluded.source, author = excluded.author, views = excluded.views, published_at = excluded.published_at, sort_order = excluded.sort_order;
insert into public.hls_news (id, title, summary, body, source, author, views, published_at, sort_order, published) values (2, '{"zh":"傳統養殖設備和現代化設備比較之全自動喂料系統","zh-CN":"传统养殖设备和现代化设备比较之全自动喂料系统","en":"Traditional and modern livestock equipment: automatic feeding systems","th":"เปรียบเทียบอุปกรณ์ปศุสัตว์แบบดั้งเดิมและสมัยใหม่: ระบบให้อาหารอัตโนมัติ"}'::jsonb, '{"zh":"在畜禽養殖生產中，冬季加熱與現代化設備對生產效率與管理具有重要影響。","zh-CN":"在畜禽养殖生产中，冬季加热与现代化设备对生产效率与管理具有重要影响。","en":"Winter heating and modern equipment can have an important impact on livestock productivity and operations.","th":"ระบบทำความร้อนในฤดูหนาวและอุปกรณ์สมัยใหม่มีผลสำคัญต่อประสิทธิภาพและการจัดการฟาร์มปศุสัตว์"}'::jsonb, '[{"zh":"在畜禽養殖生產過程中，冬季畜禽舍加熱取暖已經成為保障生產成績的必要條件。","zh-CN":"在畜禽养殖生产过程中，冬季畜禽舍加热取暖已经成为保障生产成绩的必要条件。","en":"In livestock production, heating animal housing in winter is essential for maintaining production performance.","th":"ในการผลิตปศุสัตว์ การให้ความอบอุ่นแก่โรงเรือนในฤดูหนาวเป็นปัจจัยสำคัญต่อประสิทธิภาพการผลิต"},{"zh":"在畜禽養殖生產過程中，冬季畜禽舍加熱取暖已經成為保障生產成績的必要條件。","zh-CN":"在畜禽养殖生产过程中，冬季畜禽舍加热取暖已经成为保障生产成绩的必要条件。","en":"In livestock production, heating animal housing in winter is essential for maintaining production performance.","th":"ในการผลิตปศุสัตว์ การให้ความอบอุ่นแก่โรงเรือนในฤดูหนาวเป็นปัจจัยสำคัญต่อประสิทธิภาพการผลิต"},{"zh":"傳統的加熱取暖模式包括熱風爐取暖、鍋爐取暖以及紅外線燈取暖等。但隨著國家政策變化（原則上不得新建10噸/時及以下的燃煤鍋爐）以及飼料成本和人工成本的提高，傳統的加熱取暖模式已經不能滿足生產需求，在這種情況下，一種高效、環保、節能的燃氣加熱器應運而生。","zh-CN":"传统的加热取暖模式包括热风炉取暖、锅炉取暖以及红外线灯取暖等。但随着国家政策变化（原则上不得新建10吨/时及以下的燃煤锅炉）以及饲料成本和人工成本的提高，传统的加热取暖模式已经不能满足生产需求，在这种情况下，一种高效、环保、节能的燃气加热器应运而生。","en":"Traditional systems include hot-air furnaces, boilers and infrared lamps. Policy changes and rising feed and labor costs created demand for efficient, cleaner and energy-saving gas heaters.","th":"ระบบแบบดั้งเดิมมีทั้งเตาลมร้อน หม้อไอน้ำ และหลอดอินฟราเรด การเปลี่ยนแปลงนโยบายรวมถึงต้นทุนอาหารสัตว์และแรงงานที่สูงขึ้น ทำให้เกิดความต้องการเครื่องทำความร้อนด้วยก๊าซที่มีประสิทธิภาพ สะอาด และประหยัดพลังงาน"},{"zh":"燃氣加熱器是一款以液化氣、天然氣或沼氣為燃料，在畜